const PATTERNS_ID_N3 = [{"jp": "あまり", "meaning_id": "terlalu, sangat sampai", "penjelasan": "Menyatakan akibat dari tingkat berlebihan suatu hal, dipakai sebagai 'あまりの~に' atau '~のあまり'.", "contoh_jp": "うれしさ の あまり、なきました。", "contoh_id": "Karena terlalu senang, saya sampai menangis."}, {"jp": "あまりに", "meaning_id": "karena terlalu", "penjelasan": "Menyatakan akibat berlebihan dari suatu keadaan/sifat.", "contoh_jp": "あまりに あつい ので、そとに でられません。", "contoh_id": "Karena terlalu panas, saya tidak bisa keluar."}, {"jp": "ば～ほど", "meaning_id": "semakin...semakin...", "penjelasan": "Menyatakan hubungan proporsional antara dua hal yang berubah bersamaan.", "contoh_jp": "べんきょう すれば する ほど、じょうず に なります。", "contoh_id": "Semakin banyak belajar, semakin pandai."}, {"jp": "ばいい", "meaning_id": "sebaiknya, alangkah baiknya", "penjelasan": "Memberi saran atau harapan dengan bentuk pengandaian ば.", "contoh_jp": "もっと はやく くれば いい です。", "contoh_id": "Sebaiknya datang lebih awal."}, {"jp": "ばかりでなく", "meaning_id": "bukan hanya...tapi juga", "penjelasan": "Menyatakan sesuatu lebih dari satu hal, menambahkan informasi lain.", "contoh_jp": "えいご ばかり でなく、ちゅうごくご も はなせます。", "contoh_id": "Bukan hanya bahasa Inggris, bisa bicara bahasa Mandarin juga."}, {"jp": "ばよかった", "meaning_id": "seharusnya, andai saja", "penjelasan": "Menyatakan penyesalan tentang sesuatu yang tidak dilakukan.", "contoh_jp": "もっと べんきょう すれば よかった。", "contoh_id": "Seharusnya saya belajar lebih giat."}, {"jp": "べき", "meaning_id": "harus, sebaiknya", "penjelasan": "Menyatakan kewajiban moral/seharusnya dilakukan.", "contoh_jp": "やくそく は まもる べき です。", "contoh_id": "Janji harus ditepati."}, {"jp": "べきではない", "meaning_id": "tidak boleh, seharusnya tidak", "penjelasan": "Bentuk negatif dari べき, menyatakan sesuatu seharusnya tidak dilakukan.", "contoh_jp": "うそ を つく べき では ない。", "contoh_id": "Seharusnya tidak berbohong."}, {"jp": "べつに～ない", "meaning_id": "tidak terlalu, tidak khusus", "penjelasan": "Menyatakan sesuatu tidak istimewa/tidak khusus, diikuti negatif.", "contoh_jp": "べつに いそがしく ありません。", "contoh_id": "Tidak terlalu sibuk."}, {"jp": "中", "meaning_id": "sedang, selama", "penjelasan": "Ditambahkan setelah kata benda untuk menyatakan 'sedang berlangsung' (dibaca ちゅう) atau 'sepanjang' (dibaca じゅう).", "contoh_jp": "かいぎ ちゅう です。", "contoh_id": "Sedang rapat."}, {"jp": "だけ (2)", "meaning_id": "sebanyak-banyaknya", "penjelasan": "Menyatakan jumlah maksimal sesuai kemampuan/keinginan.", "contoh_jp": "たべたい だけ たべて ください。", "contoh_id": "Silakan makan sebanyak yang kamu mau."}, {"jp": "だらけ", "meaning_id": "penuh dengan", "penjelasan": "Menyatakan sesuatu penuh dipenuhi hal yang tidak diinginkan.", "contoh_jp": "どろ だらけ の くつ です。", "contoh_id": "Sepatu yang penuh lumpur."}, {"jp": "どころか", "meaning_id": "jangankan..., malah", "penjelasan": "Menyatakan kenyataan yang jauh berbeda/berlawanan dari yang diharapkan.", "contoh_jp": "やすむ どころか、もっと いそがしく なりました。", "contoh_id": "Jangankan istirahat, malah tambah sibuk."}, {"jp": "どんなに～ても", "meaning_id": "betapa pun, sekalipun", "penjelasan": "Menekankan bahwa hasil tetap sama meski tingkat kondisi ekstrem.", "contoh_jp": "どんなに つかれて も、がんばります。", "contoh_id": "Sekalipun sangat lelah, saya akan tetap berusaha."}, {"jp": "ふりをする", "meaning_id": "berpura-pura", "penjelasan": "Menyatakan tindakan berpura-pura melakukan/menjadi sesuatu.", "contoh_jp": "しらない ふり を しました。", "contoh_id": "Berpura-pura tidak tahu."}, {"jp": "ふと", "meaning_id": "tiba-tiba, tanpa sengaja", "penjelasan": "Menyatakan sesuatu terjadi/terpikir secara spontan.", "contoh_jp": "ふと おもいだしました。", "contoh_id": "Tiba-tiba teringat."}, {"jp": "がち", "meaning_id": "cenderung, sering", "penjelasan": "Menyatakan kecenderungan negatif yang sering terjadi.", "contoh_jp": "わすれがち です。", "contoh_id": "Sering lupa."}, {"jp": "がたい", "meaning_id": "sulit sekali untuk", "penjelasan": "Menyatakan sesuatu sangat sulit dilakukan, biasanya untuk hal abstrak.", "contoh_jp": "しんじがたい はなし です。", "contoh_id": "Cerita yang sulit dipercaya."}, {"jp": "ぎみ", "meaning_id": "agak, sedikit (kecenderungan)", "penjelasan": "Menyatakan kondisi sedikit mengarah ke suatu keadaan.", "contoh_jp": "かぜぎみ です。", "contoh_id": "Agak masuk angin."}, {"jp": "ほど", "meaning_id": "sampai-sampai, sedemikian", "penjelasan": "Menyatakan tingkat/derajat sesuatu dengan memberi perbandingan.", "contoh_jp": "なみだ が でる ほど わらいました。", "contoh_id": "Tertawa sampai-sampai keluar air mata."}, {"jp": "ほど～ない", "meaning_id": "tidak se... seperti", "penjelasan": "Membandingkan dua hal, menyatakan sesuatu tidak setingkat yang lain.", "contoh_jp": "きょう は きのう ほど さむく ない。", "contoh_id": "Hari ini tidak sedingin kemarin."}, {"jp": "いくら～ても", "meaning_id": "betapa pun, meski seberapa", "penjelasan": "Menekankan hasil tetap sama meski usaha/kondisi ekstrem.", "contoh_jp": "いくら よんでも、へんじ が ない。", "contoh_id": "Sebanyak apa pun dipanggil, tidak ada jawaban."}, {"jp": "一方だ", "meaning_id": "semakin, terus-menerus", "penjelasan": "Menyatakan perubahan yang terus berlanjut ke satu arah.", "contoh_jp": "ぶっか が あがる いっぽう です。", "contoh_id": "Harga barang terus naik."}, {"jp": "一方で", "meaning_id": "di satu sisi...di sisi lain", "penjelasan": "Menyatakan dua aspek berbeda dari satu hal.", "contoh_jp": "べんり な いっぽう で、たかい です。", "contoh_id": "Di satu sisi praktis, di sisi lain mahal."}, {"jp": "かけ", "meaning_id": "belum selesai, setengah", "penjelasan": "Menyatakan sesuatu baru dimulai/belum selesai sepenuhnya.", "contoh_jp": "たべかけ の りんご です。", "contoh_id": "Apel yang baru dimakan setengah."}, {"jp": "代わりに", "meaning_id": "sebagai gantinya", "penjelasan": "Menyatakan sesuatu dilakukan sebagai pengganti hal lain.", "contoh_jp": "わたし の かわりに いって ください。", "contoh_id": "Tolong pergi sebagai gantiku."}, {"jp": "っけ", "meaning_id": "ya, kira-kira apa ya", "penjelasan": "Menyatakan mengingat-ingat sesuatu, bentuk santai.", "contoh_jp": "あした は なんようび だっけ。", "contoh_id": "Besok hari apa ya?"}, {"jp": "決して～ない", "meaning_id": "sama sekali tidak, tidak pernah", "penjelasan": "Menekankan negasi kuat, biasanya untuk janji/tekad.", "contoh_jp": "けっして わすれません。", "contoh_id": "Saya tidak akan pernah lupa."}, {"jp": "切る", "meaning_id": "melakukan sampai tuntas", "penjelasan": "Ditambahkan pada kata kerja untuk menyatakan sesuatu diselesaikan sepenuhnya.", "contoh_jp": "つかれきりました。", "contoh_id": "Sudah sangat kelelahan (habis-habisan)."}, {"jp": "切れない", "meaning_id": "tidak sanggup menyelesaikan", "penjelasan": "Menyatakan sesuatu terlalu banyak untuk diselesaikan.", "contoh_jp": "たべきれません。", "contoh_id": "Tidak sanggup menghabiskannya."}, {"jp": "きり", "meaning_id": "hanya, sejak itu saja", "penjelasan": "Menyatakan sesuatu terjadi hanya sekali/terbatas sejak saat itu.", "contoh_jp": "いちど きり の けいけん です。", "contoh_id": "Pengalaman yang hanya sekali seumur hidup."}, {"jp": "こそ", "meaning_id": "justru, memang", "penjelasan": "Menekankan kata di depannya dengan penegasan kuat.", "contoh_jp": "こんど こそ がんばります。", "contoh_id": "Kali ini justru saya akan berusaha keras."}, {"jp": "こと", "meaning_id": "harus (perintah tertulis)", "penjelasan": "Bentuk formal untuk menyatakan aturan/keharusan, sering di papan pengumuman.", "contoh_jp": "きそく を まもる こと。", "contoh_id": "Harus mematuhi peraturan."}, {"jp": "ことだ", "meaning_id": "sebaiknya", "penjelasan": "Memberi nasihat/saran dengan nada tegas.", "contoh_jp": "はやく ねる こと です。", "contoh_id": "Sebaiknya cepat tidur."}, {"jp": "ことがある", "meaning_id": "kadang-kadang terjadi", "penjelasan": "Menyatakan sesuatu kadang terjadi meski tidak selalu.", "contoh_jp": "ときどき ちこく する こと が あります。", "contoh_id": "Kadang-kadang terlambat."}, {"jp": "ことか", "meaning_id": "betapa...!", "penjelasan": "Menyatakan seruan emosional tentang tingkat sesuatu.", "contoh_jp": "どんなに うれしかった こと か。", "contoh_id": "Betapa senangnya!"}, {"jp": "ことに", "meaning_id": "anehnya, uniknya", "penjelasan": "Menyatakan reaksi pembicara terhadap suatu fakta.", "contoh_jp": "おどろいた こと に、かれ が きました。", "contoh_id": "Anehnya, dia datang."}, {"jp": "ことはない", "meaning_id": "tidak perlu", "penjelasan": "Menyatakan sesuatu tidak perlu dilakukan.", "contoh_jp": "しんぱい する こと は ない。", "contoh_id": "Tidak perlu khawatir."}, {"jp": "くらい", "meaning_id": "sampai segitunya", "penjelasan": "Menyatakan tingkat kecil/remeh dari suatu hal sebagai perbandingan.", "contoh_jp": "あるく くらい なら、でんしゃ に のります。", "contoh_id": "Daripada jalan kaki, lebih baik naik kereta."}, {"jp": "くせに", "meaning_id": "padahal, walaupun (nada mencela)", "penjelasan": "Menyatakan pertentangan dengan nada kritik/mencela.", "contoh_jp": "しらない くせに、しっている ふり を する。", "contoh_id": "Padahal tidak tahu, berpura-pura tahu."}, {"jp": "まま", "meaning_id": "tetap seperti apa adanya", "penjelasan": "Menyatakan keadaan tidak berubah selama suatu tindakan berlangsung.", "contoh_jp": "くつ を はいた まま、へや に はいりました。", "contoh_id": "Masuk ke kamar dengan sepatu masih dipakai."}, {"jp": "まるで", "meaning_id": "seolah-olah, persis seperti", "penjelasan": "Menekankan perumpamaan yang sangat mirip.", "contoh_jp": "まるで ゆめ の よう です。", "contoh_id": "Seperti mimpi saja."}, {"jp": "めったに～ない", "meaning_id": "jarang sekali", "penjelasan": "Menyatakan frekuensi yang sangat rendah, diikuti negatif.", "contoh_jp": "めったに びょうき に なりません。", "contoh_id": "Jarang sekali sakit."}, {"jp": "もの", "meaning_id": "habisnya, soalnya", "penjelasan": "Memberi alasan/alibi dengan nada agak manja, bentuk santai.", "contoh_jp": "だって、いそがしい んだもの。", "contoh_id": "Habisnya, saya sibuk."}, {"jp": "ものだ", "meaning_id": "dulu biasa, seharusnya (kodrat)", "penjelasan": "Menyatakan kebiasaan masa lalu atau kebenaran umum.", "contoh_jp": "むかし よく あそんだ もの です。", "contoh_id": "Dulu sering bermain."}, {"jp": "もしかしたら", "meaning_id": "barangkali, jangan-jangan", "penjelasan": "Menyatakan kemungkinan yang tidak yakin.", "contoh_jp": "もしかしたら、あめ かも しれません。", "contoh_id": "Barangkali akan hujan."}, {"jp": "向き", "meaning_id": "cocok untuk", "penjelasan": "Menyatakan sesuatu sesuai untuk suatu kelompok/tujuan.", "contoh_jp": "こども むき の えいが です。", "contoh_id": "Film yang cocok untuk anak-anak."}, {"jp": "向け", "meaning_id": "ditujukan untuk", "penjelasan": "Menyatakan sesuatu dibuat khusus untuk kelompok sasaran tertentu.", "contoh_jp": "がいこくじん むけ の サービス です。", "contoh_id": "Layanan yang ditujukan untuk orang asing."}, {"jp": "ながらも", "meaning_id": "meskipun, walaupun", "penjelasan": "Menyatakan pertentangan antara dua keadaan yang terjadi bersamaan.", "contoh_jp": "わかい ながらも、しっかり して います。", "contoh_id": "Meskipun masih muda, dia sudah dewasa."}, {"jp": "ないことはない", "meaning_id": "bukan tidak mungkin", "penjelasan": "Menyatakan kemungkinan dengan nada ragu-ragu (dua negatif).", "contoh_jp": "いけない こと は ない です。", "contoh_id": "Bukannya tidak bisa pergi."}, {"jp": "なんか / なんて", "meaning_id": "seperti, hal semacam", "penjelasan": "Menyebutkan sesuatu dengan nada meremehkan/santai.", "contoh_jp": "べんきょう なんて きらい です。", "contoh_id": "Hal seperti belajar, saya benci."}, {"jp": "なるべく", "meaning_id": "sebisa mungkin", "penjelasan": "Menyatakan usaha maksimal untuk melakukan sesuatu.", "contoh_jp": "なるべく はやく きて ください。", "contoh_id": "Tolong datang sebisa mungkin lebih awal."}, {"jp": "なぜなら", "meaning_id": "karena, alasannya adalah", "penjelasan": "Memberikan alasan untuk kalimat sebelumnya, bentuk formal.", "contoh_jp": "いきません。なぜなら、いそがしい から です。", "contoh_id": "Saya tidak pergi. Karena saya sibuk."}, {"jp": "に違いない", "meaning_id": "pasti, yakin", "penjelasan": "Menyatakan keyakinan kuat berdasarkan bukti.", "contoh_jp": "かれ は にほんじん に ちがいない。", "contoh_id": "Dia pasti orang Jepang."}, {"jp": "にかけて", "meaning_id": "menjelang, sekitar (rentang)", "penjelasan": "Menyatakan rentang waktu/tempat dari satu titik ke titik lain.", "contoh_jp": "あき から ふゆ に かけて さむく なります。", "contoh_id": "Dari musim gugur menjelang musim dingin, cuaca menjadi dingin."}, {"jp": "に関する / に関して", "meaning_id": "mengenai, terkait dengan", "penjelasan": "Menandai topik pembahasan.", "contoh_jp": "けいざい に かんする ニュース です。", "contoh_id": "Berita mengenai ekonomi."}, {"jp": "にかわって", "meaning_id": "mewakili, menggantikan", "penjelasan": "Menyatakan sesuatu dilakukan sebagai pengganti orang lain.", "contoh_jp": "しゃちょう に かわって あいさつ します。", "contoh_id": "Menyampaikan sambutan mewakili direktur."}, {"jp": "に比べて", "meaning_id": "dibandingkan dengan", "penjelasan": "Menyatakan perbandingan antara dua hal.", "contoh_jp": "きょねん に くらべて あつい です。", "contoh_id": "Dibandingkan tahun lalu, lebih panas."}, {"jp": "において/ における", "meaning_id": "di, dalam (formal)", "penjelasan": "Menandai tempat/bidang secara formal.", "contoh_jp": "にほん に おいて、それ は ふつう です。", "contoh_id": "Di Jepang, hal itu biasa."}, {"jp": "にしては", "meaning_id": "untuk ukuran, dibanding", "penjelasan": "Menyatakan sesuatu tidak sesuai ekspektasi berdasarkan kategorinya.", "contoh_jp": "にほんじん に しては、えいご が じょうず です。", "contoh_id": "Untuk ukuran orang Jepang, bahasa Inggrisnya bagus."}, {"jp": "にしても", "meaning_id": "meskipun, sekalipun", "penjelasan": "Menyatakan pengecualian meski suatu kondisi terpenuhi.", "contoh_jp": "いそがしい に しても、れんらく すべき です。", "contoh_id": "Sekalipun sibuk, seharusnya tetap menghubungi."}, {"jp": "に対して", "meaning_id": "terhadap, kepada", "penjelasan": "Menandai objek atau sasaran suatu sikap/tindakan.", "contoh_jp": "せんせい に たいして しつれい です。", "contoh_id": "Tidak sopan terhadap guru."}, {"jp": "にとって", "meaning_id": "bagi", "penjelasan": "Menyatakan sudut pandang seseorang/sesuatu.", "contoh_jp": "わたし に とって たいせつ な もの です。", "contoh_id": "Sesuatu yang penting bagi saya."}, {"jp": "について", "meaning_id": "tentang, mengenai", "penjelasan": "Menandai topik pembicaraan.", "contoh_jp": "にほん に ついて はなします。", "contoh_id": "Berbicara tentang Jepang."}, {"jp": "につれて", "meaning_id": "seiring dengan", "penjelasan": "Menyatakan dua perubahan terjadi bersamaan.", "contoh_jp": "としをとる に つれて、わすれっぽく なる。", "contoh_id": "Seiring bertambah usia, jadi mudah lupa."}, {"jp": "によると / によれば", "meaning_id": "menurut", "penjelasan": "Menandai sumber informasi.", "contoh_jp": "てんきよほう に よると、あした は あめ です。", "contoh_id": "Menurut ramalan cuaca, besok hujan."}, {"jp": "によって / による", "meaning_id": "tergantung, disebabkan oleh", "penjelasan": "Menandai penyebab atau sarana; juga menyatakan variasi tergantung sesuatu.", "contoh_jp": "ひと に よって かんがえ が ちがいます。", "contoh_id": "Pendapat berbeda tergantung orangnya."}, {"jp": "の間に", "meaning_id": "selama, di antara", "penjelasan": "Menyatakan sesuatu terjadi dalam suatu rentang waktu.", "contoh_jp": "やすみ の あいだ に りょこう しました。", "contoh_id": "Selama liburan, saya bepergian."}, {"jp": "を中心に", "meaning_id": "berpusat pada", "penjelasan": "Menandai pusat/fokus utama suatu hal.", "contoh_jp": "とうきょう を ちゅうしん に はってん しました。", "contoh_id": "Berkembang berpusat di Tokyo."}, {"jp": "をはじめ", "meaning_id": "termasuk, dimulai dari", "penjelasan": "Menyebutkan contoh utama dari suatu kelompok.", "contoh_jp": "にほん を はじめ、アジア の くに。", "contoh_id": "Negara-negara Asia, termasuk Jepang."}, {"jp": "おかげで", "meaning_id": "berkat", "penjelasan": "Menyatakan sebab positif dari suatu hasil baik.", "contoh_jp": "せんせい の おかげ で ごうかく しました。", "contoh_id": "Berkat guru, saya lulus ujian."}, {"jp": "おそらく", "meaning_id": "mungkin, kemungkinan besar", "penjelasan": "Menyatakan dugaan dengan tingkat keyakinan cukup tinggi.", "contoh_jp": "おそらく かれ は こない でしょう。", "contoh_id": "Kemungkinan besar dia tidak akan datang."}, {"jp": "っぱなし", "meaning_id": "dibiarkan begitu saja", "penjelasan": "Menyatakan sesuatu dibiarkan dalam keadaan tertentu tanpa diurus.", "contoh_jp": "ドア を あけっぱなし に しないで ください。", "contoh_id": "Jangan biarkan pintu terbuka begitu saja."}, {"jp": "っぽい", "meaning_id": "cenderung, mirip", "penjelasan": "Menyatakan sesuatu memiliki karakteristik/kecenderungan tertentu.", "contoh_jp": "こどもっぽい です ね。", "contoh_id": "Kekanak-kanakan, ya."}, {"jp": "さえ", "meaning_id": "bahkan", "penjelasan": "Menekankan hal ekstrem sebagai contoh untuk menyiratkan hal lain lebih jelas.", "contoh_jp": "かんじ さえ よめません。", "contoh_id": "Bahkan kanji pun tidak bisa dibaca."}, {"jp": "さえ～ば", "meaning_id": "asalkan, kalau saja", "penjelasan": "Menyatakan syarat minimal yang cukup untuk mencapai hasil.", "contoh_jp": "おかね さえ あれば、かえます。", "contoh_id": "Asalkan ada uang, bisa membelinya."}, {"jp": "最中に", "meaning_id": "di tengah-tengah", "penjelasan": "Menyatakan sesuatu terjadi saat kegiatan lain sedang berlangsung.", "contoh_jp": "かいぎ の さいちゅう に でんわ が なりました。", "contoh_id": "Telepon berbunyi di tengah-tengah rapat."}, {"jp": "せいで", "meaning_id": "gara-gara, akibat", "penjelasan": "Menyatakan sebab negatif dari suatu hasil buruk.", "contoh_jp": "あめ の せい で、ちこく しました。", "contoh_id": "Gara-gara hujan, saya terlambat."}, {"jp": "しかない", "meaning_id": "tidak ada pilihan lain selain", "penjelasan": "Menyatakan satu-satunya pilihan yang tersisa.", "contoh_jp": "あるく しか ない です。", "contoh_id": "Tidak ada pilihan lain selain berjalan kaki."}, {"jp": "その結果", "meaning_id": "sebagai hasilnya", "penjelasan": "Menghubungkan sebab dengan akibat yang terjadi.", "contoh_jp": "どりょく しました。その けっか、ごうかく しました。", "contoh_id": "Sudah berusaha keras. Sebagai hasilnya, lulus."}, {"jp": "そうもない", "meaning_id": "sepertinya tidak akan", "penjelasan": "Menyatakan dugaan kuat bahwa sesuatu tidak akan terjadi.", "contoh_jp": "あめ が やみそう も ない。", "contoh_id": "Sepertinya hujan tidak akan berhenti."}, {"jp": "たびに", "meaning_id": "setiap kali", "penjelasan": "Menyatakan sesuatu selalu terjadi setiap kali kondisi tertentu muncul.", "contoh_jp": "かれ に あう たびに、げんき に なります。", "contoh_id": "Setiap kali bertemu dia, jadi semangat."}, {"jp": "ために 1", "meaning_id": "demi, untuk", "penjelasan": "Menyatakan tujuan suatu tindakan.", "contoh_jp": "かぞく の ために はたらきます。", "contoh_id": "Bekerja demi keluarga."}, {"jp": "ために 2", "meaning_id": "karena, akibat", "penjelasan": "Menyatakan penyebab suatu keadaan (bukan tujuan).", "contoh_jp": "じこ の ために、でんしゃ が とまりました。", "contoh_id": "Akibat kecelakaan, kereta berhenti."}, {"jp": "たらいい/といい", "meaning_id": "semoga, alangkah baiknya", "penjelasan": "Menyatakan harapan pembicara.", "contoh_jp": "あした はれたら いい です ね。", "contoh_id": "Semoga besok cerah ya."}, {"jp": "確かに", "meaning_id": "memang benar", "penjelasan": "Mengakui kebenaran suatu pernyataan sebelum memberi tanggapan lain.", "contoh_jp": "たしかに、それ は そう です。", "contoh_id": "Memang benar, itu betul."}, {"jp": "たとえ～ても", "meaning_id": "sekalipun, walaupun", "penjelasan": "Menyatakan hasil tetap sama meski kondisi ekstrem terjadi.", "contoh_jp": "たとえ あめ が ふって も、いきます。", "contoh_id": "Sekalipun hujan turun, saya akan tetap pergi."}, {"jp": "たとえば", "meaning_id": "misalnya, contohnya", "penjelasan": "Memberikan contoh konkret.", "contoh_jp": "くだもの、たとえば りんご が すき です。", "contoh_id": "Saya suka buah, misalnya apel."}, {"jp": "た結果 / の結果", "meaning_id": "sebagai hasil dari", "penjelasan": "Menyatakan hasil dari suatu proses/tindakan.", "contoh_jp": "はなしあった けっか、けっていしました。", "contoh_id": "Sebagai hasil diskusi, sudah diputuskan."}, {"jp": "たとたん", "meaning_id": "begitu, tepat saat", "penjelasan": "Menyatakan sesuatu terjadi tepat setelah kejadian lain.", "contoh_jp": "ドア を あけた とたん、あめ が ふりだした。", "contoh_id": "Begitu membuka pintu, hujan mulai turun."}, {"jp": "てごらん", "meaning_id": "coba lakukan (lembut)", "penjelasan": "Ajakan mencoba sesuatu dengan nada lembut/ramah.", "contoh_jp": "たべて ごらん。", "contoh_id": "Coba dimakan."}, {"jp": "てはじめて", "meaning_id": "baru setelah, baru sadar", "penjelasan": "Menyatakan sesuatu baru disadari/terjadi setelah suatu kejadian.", "contoh_jp": "うしなって はじめて、たいせつさ が わかった。", "contoh_id": "Baru sadar pentingnya setelah kehilangan."}, {"jp": "てもかまわない", "meaning_id": "tidak masalah, boleh saja", "penjelasan": "Menyatakan izin dengan nada santai.", "contoh_jp": "かえって も かまいません。", "contoh_id": "Boleh saja pulang."}, {"jp": "途中に/途中で", "meaning_id": "di tengah jalan, dalam perjalanan", "penjelasan": "Menyatakan sesuatu terjadi saat suatu proses/perjalanan belum selesai.", "contoh_jp": "かいしゃ に いく とちゅう で あいました。", "contoh_id": "Bertemu di tengah perjalanan ke kantor."}, {"jp": "といっても", "meaning_id": "meski dikatakan begitu", "penjelasan": "Mengoreksi kesan berlebihan dari pernyataan sebelumnya.", "contoh_jp": "かんたん と いっても、じかん が かかります。", "contoh_id": "Meski dikatakan mudah, tetap butuh waktu."}, {"jp": "という", "meaning_id": "yang disebut, bernama", "penjelasan": "Menandai nama/istilah suatu hal.", "contoh_jp": "ふじさん という やま。", "contoh_id": "Gunung yang bernama Fuji."}, {"jp": "ということだ", "meaning_id": "katanya, artinya", "penjelasan": "Menyampaikan informasi dari sumber lain (hearsay) secara formal.", "contoh_jp": "あした やすみ と いう こと です。", "contoh_id": "Katanya besok libur."}, {"jp": "というのは", "meaning_id": "yang dimaksud adalah, sebab", "penjelasan": "Menjelaskan/mendefinisikan sesuatu yang disebut sebelumnya.", "contoh_jp": "かのじょ が こない と いう の は、びょうき だから です。", "contoh_id": "Alasan dia tidak datang karena sakit."}, {"jp": "というと", "meaning_id": "kalau bicara soal", "penjelasan": "Mengalihkan topik berdasarkan kata yang baru disebutkan.", "contoh_jp": "にほん と いう と、さくら を おもいだします。", "contoh_id": "Kalau bicara soal Jepang, saya ingat sakura."}, {"jp": "というより", "meaning_id": "lebih tepatnya, daripada", "penjelasan": "Mengoreksi ungkapan sebelumnya dengan yang lebih tepat.", "contoh_jp": "すき と いう より、あいして います。", "contoh_id": "Lebih tepatnya bukan suka, tapi cinta."}, {"jp": "ところで", "meaning_id": "omong-omong", "penjelasan": "Mengalihkan topik pembicaraan.", "contoh_jp": "ところで、あした あいますか。", "contoh_id": "Omong-omong, besok ketemu?"}, {"jp": "ところが", "meaning_id": "namun, tetapi ternyata", "penjelasan": "Menyatakan hasil tak terduga yang berlawanan dengan harapan.", "contoh_jp": "がんばりました。ところが、しっぱい しました。", "contoh_id": "Sudah berusaha keras. Namun ternyata gagal."}, {"jp": "とおり", "meaning_id": "sesuai, seperti", "penjelasan": "Menyatakan sesuatu dilakukan persis sesuai contoh/petunjuk.", "contoh_jp": "せつめい の とおり に して ください。", "contoh_id": "Tolong lakukan sesuai penjelasan."}, {"jp": "としたら / とすれば", "meaning_id": "seandainya, kalau begitu", "penjelasan": "Bentuk pengandaian berdasarkan asumsi.", "contoh_jp": "もし いく と したら、いつ です か。", "contoh_id": "Seandainya pergi, kapan?"}, {"jp": "として", "meaning_id": "sebagai", "penjelasan": "Menandai peran/kedudukan seseorang atau sesuatu.", "contoh_jp": "せんせい として はたらいて います。", "contoh_id": "Bekerja sebagai guru."}, {"jp": "とは限らない", "meaning_id": "belum tentu", "penjelasan": "Menyatakan sesuatu tidak selalu benar.", "contoh_jp": "たかい もの が いい とは かぎりません。", "contoh_id": "Barang mahal belum tentu bagus."}, {"jp": "ついでに", "meaning_id": "sekalian", "penjelasan": "Menyatakan melakukan sesuatu bersamaan dengan kegiatan lain.", "contoh_jp": "かいもの の ついでに、ぎんこう に いきました。", "contoh_id": "Sekalian belanja, pergi ke bank juga."}, {"jp": "つまり", "meaning_id": "dengan kata lain, jadi", "penjelasan": "Merangkum atau menegaskan ulang dengan cara berbeda.", "contoh_jp": "つまり、これ は だめ と いう こと です ね。", "contoh_id": "Dengan kata lain, ini tidak boleh, ya."}, {"jp": "と共に", "meaning_id": "bersama dengan, seiring", "penjelasan": "Menyatakan dua hal terjadi/berlangsung bersamaan.", "contoh_jp": "かぞく と ともに くらして います。", "contoh_id": "Tinggal bersama keluarga."}, {"jp": "うちに", "meaning_id": "selagi, sebelum", "penjelasan": "Menyatakan sesuatu dilakukan sebelum keadaan berubah.", "contoh_jp": "あかるい うちに、かえりましょう。", "contoh_id": "Ayo pulang selagi masih terang."}, {"jp": "わけだ", "meaning_id": "pantas saja, jadi begitu", "penjelasan": "Menyimpulkan sesuatu berdasarkan alasan logis.", "contoh_jp": "どうりで さむい わけだ。", "contoh_id": "Pantas saja dingin."}, {"jp": "わけではない", "meaning_id": "bukan berarti", "penjelasan": "Mengoreksi kesimpulan berlebihan yang mungkin diambil lawan bicara.", "contoh_jp": "きらい な わけ では ありません。", "contoh_id": "Bukan berarti saya benci."}, {"jp": "わけがない", "meaning_id": "tidak mungkin", "penjelasan": "Menyatakan sesuatu mustahil terjadi.", "contoh_jp": "できる わけ が ない。", "contoh_id": "Tidak mungkin bisa."}, {"jp": "わけにはいかない", "meaning_id": "tidak bisa begitu saja", "penjelasan": "Menyatakan sesuatu tidak bisa dilakukan karena alasan sosial/moral.", "contoh_jp": "やすむ わけ には いきません。", "contoh_id": "Tidak bisa begitu saja libur."}, {"jp": "わりに", "meaning_id": "padahal, meski begitu", "penjelasan": "Menyatakan hasil tidak sesuai ekspektasi berdasarkan kondisi awal.", "contoh_jp": "やすい わりに、おいしい です。", "contoh_id": "Meski murah, ternyata enak."}, {"jp": "ような気がする", "meaning_id": "merasa seperti", "penjelasan": "Menyatakan perasaan/firasat pembicara.", "contoh_jp": "だれか いる よう な き が します。", "contoh_id": "Merasa seperti ada seseorang."}, {"jp": "ように", "meaning_id": "agar, supaya", "penjelasan": "Menyatakan tujuan dengan kata kerja yang tidak bisa dikontrol langsung.", "contoh_jp": "わすれない よう に、メモ します。", "contoh_id": "Mencatat agar tidak lupa."}, {"jp": "ようとする", "meaning_id": "berusaha, hendak", "penjelasan": "Menyatakan usaha/niat untuk melakukan sesuatu.", "contoh_jp": "でかけよう と した とき、でんわ が なりました。", "contoh_id": "Saat hendak keluar, telepon berbunyi."}, {"jp": "ようとしない", "meaning_id": "tidak mau berusaha", "penjelasan": "Menyatakan penolakan untuk mencoba melakukan sesuatu.", "contoh_jp": "たべよう と しません。", "contoh_id": "Tidak mau berusaha makan."}, {"jp": "ずに", "meaning_id": "tanpa melakukan", "penjelasan": "Bentuk formal dari ないで, menyatakan sesuatu dilakukan tanpa hal lain.", "contoh_jp": "なにも いわずに でて いきました。", "contoh_id": "Pergi tanpa mengatakan apa-apa."}, {"jp": "ずにはいられない", "meaning_id": "tidak bisa menahan diri untuk tidak", "penjelasan": "Menyatakan dorongan kuat yang tidak bisa ditahan.", "contoh_jp": "わらわずには いられません。", "contoh_id": "Tidak bisa menahan diri untuk tidak tertawa."}];
/* ====== TERJEMAHAN INDONESIA — POLA KALIMAT N2 (tahap 4, TERAKHIR) ====== */
const PATTERNS_ID_N2 = [{"jp": "あるいは", "meaning_id": "atau, mungkin juga", "penjelasan": "Kata sambung formal yang berarti 'atau', bisa juga berarti 'mungkin'.", "contoh_jp": "ペン あるいは えんぴつ で かいて ください。", "contoh_id": "Tolong tulis dengan pena atau pensil."}, {"jp": "ばかり (2)", "meaning_id": "kira-kira, sekitar", "penjelasan": "Menyatakan perkiraan jumlah, mirip くらい.", "contoh_jp": "じゅっぷん ばかり まって ください。", "contoh_id": "Tolong tunggu sekitar sepuluh menit."}, {"jp": "ばかりだ", "meaning_id": "terus-menerus (memburuk/meningkat)", "penjelasan": "Menyatakan perubahan yang terus berlanjut ke satu arah.", "contoh_jp": "びょうき が わるく なる ばかり です。", "contoh_id": "Penyakitnya terus memburuk."}, {"jp": "ばかりに", "meaning_id": "gara-gara, hanya karena", "penjelasan": "Menyatakan sebab kecil yang menimbulkan akibat besar/negatif.", "contoh_jp": "おくれた ばかり に、でんしゃ に のれなかった。", "contoh_id": "Gara-gara terlambat, tidak bisa naik kereta."}, {"jp": "ぶりに", "meaning_id": "setelah sekian lama", "penjelasan": "Menyatakan sesuatu terjadi lagi setelah rentang waktu tertentu.", "contoh_jp": "いちねん ぶり に あいました。", "contoh_id": "Bertemu lagi setelah satu tahun."}, {"jp": "ちっとも～ない", "meaning_id": "sama sekali tidak", "penjelasan": "Bentuk penekanan negasi yang kuat, bahasa santai.", "contoh_jp": "ちっとも おもしろく ない。", "contoh_id": "Sama sekali tidak menarik."}, {"jp": "だけあって", "meaning_id": "pantas saja, sesuai dengan", "penjelasan": "Menyatakan hasil yang wajar mengingat suatu kondisi/status.", "contoh_jp": "がいこく に すんでいた だけ あって、えいご が じょうず です。", "contoh_id": "Pantas saja bahasa Inggrisnya bagus, dia pernah tinggal di luar negeri."}, {"jp": "だけでなく", "meaning_id": "bukan hanya...tapi juga", "penjelasan": "Menambahkan informasi lain selain yang sudah disebutkan.", "contoh_jp": "にほんご だけ でなく、ちゅうごくご も はなせます。", "contoh_id": "Bukan hanya bahasa Jepang, bisa bicara bahasa Mandarin juga."}, {"jp": "だけましだ", "meaning_id": "untung saja, patut disyukuri", "penjelasan": "Menyatakan sesuatu yang buruk masih lebih baik dari kemungkinan terburuk.", "contoh_jp": "けが だけ で すんで ました な。", "contoh_id": "Untung saja hanya luka ringan."}, {"jp": "だけに", "meaning_id": "justru karena", "penjelasan": "Menekankan alasan yang membuat suatu hasil semakin masuk akal.", "contoh_jp": "がんばった だけ に、うれしい です。", "contoh_id": "Justru karena sudah berusaha keras, jadi senang."}, {"jp": "だけのことはある", "meaning_id": "pantas saja", "penjelasan": "Menyatakan hasil yang sepadan dengan usaha/status seseorang.", "contoh_jp": "さすが プロ だけ の こと は ある。", "contoh_id": "Pantas saja, memang profesional."}, {"jp": "だけは", "meaning_id": "setidaknya, paling tidak", "penjelasan": "Menekankan satu hal minimal yang tetap dilakukan.", "contoh_jp": "これ だけ は やります。", "contoh_id": "Setidaknya ini akan saya lakukan."}, {"jp": "だって", "meaning_id": "habisnya, tapi", "penjelasan": "Alasan dengan nada informal, sering dipakai anak-anak/santai.", "contoh_jp": "だって、じかん が なかった んだもの。", "contoh_id": "Habisnya, tidak ada waktu."}, {"jp": "すら (de sura)", "meaning_id": "bahkan", "penjelasan": "Menekankan hal ekstrem sebagai contoh, mirip さえ tapi lebih formal.", "contoh_jp": "こども ですら わかります。", "contoh_id": "Bahkan anak kecil pun mengerti."}, {"jp": "ではないか", "meaning_id": "bukankah, ayo", "penjelasan": "Menegaskan sesuatu atau mengajak dengan nada retoris.", "contoh_jp": "やって みよう では ないか。", "contoh_id": "Ayo kita coba, bukan?"}, {"jp": "でしかない", "meaning_id": "tidak lebih dari", "penjelasan": "Menyatakan sesuatu terbatas hanya sebatas itu saja.", "contoh_jp": "それ は うわさ でしか ない。", "contoh_id": "Itu tidak lebih dari sekadar gosip."}, {"jp": "どころではない", "meaning_id": "bukan saatnya untuk", "penjelasan": "Menyatakan situasi tidak memungkinkan untuk melakukan sesuatu.", "contoh_jp": "いま りょこう どころ では ない。", "contoh_id": "Sekarang bukan saatnya untuk bepergian."}, {"jp": "どうせ", "meaning_id": "toh, bagaimanapun juga", "penjelasan": "Menyatakan hasil tidak akan berubah apapun yang dilakukan, nada pasrah.", "contoh_jp": "どうせ むり です。", "contoh_id": "Toh tetap tidak mungkin."}, {"jp": "どうやら", "meaning_id": "sepertinya", "penjelasan": "Menyatakan dugaan berdasarkan tanda-tanda yang terlihat.", "contoh_jp": "どうやら あめ が やんだ よう です。", "contoh_id": "Sepertinya hujan sudah berhenti."}, {"jp": "える / うる", "meaning_id": "bisa, mungkin", "penjelasan": "Akhiran formal yang menyatakan kemungkinan/kemampuan.", "contoh_jp": "それ は ありえる はなし です。", "contoh_id": "Itu cerita yang mungkin terjadi."}, {"jp": "えない", "meaning_id": "tidak mungkin, tidak bisa", "penjelasan": "Bentuk negatif dari える/うる.", "contoh_jp": "しんじられない はなし です。", "contoh_id": "Cerita yang tidak bisa dipercaya."}, {"jp": "ふたたび", "meaning_id": "lagi, sekali lagi", "penjelasan": "Kata keterangan formal yang berarti 'lagi'.", "contoh_jp": "ふたたび あえて うれしい です。", "contoh_id": "Senang bisa bertemu lagi."}, {"jp": "ふうに", "meaning_id": "dengan cara begini/begitu", "penjelasan": "Menyatakan cara/gaya melakukan sesuatu.", "contoh_jp": "この ふう に して ください。", "contoh_id": "Tolong lakukan dengan cara begini."}, {"jp": "げ", "meaning_id": "terlihat, kelihatan", "penjelasan": "Akhiran yang menyatakan kesan visual dari suatu keadaan.", "contoh_jp": "かなしげ な かお。", "contoh_id": "Wajah yang terlihat sedih."}, {"jp": "ごとに", "meaning_id": "setiap", "penjelasan": "Menyatakan pengulangan pada interval/kelompok tertentu.", "contoh_jp": "いちねん ごと に けんさ します。", "contoh_id": "Memeriksa setiap satu tahun."}, {"jp": "逆に", "meaning_id": "sebaliknya", "penjelasan": "Menyatakan hal yang berlawanan dari yang diharapkan/disebutkan.", "contoh_jp": "ぎゃくに、それ は よく ない です。", "contoh_id": "Sebaliknya, itu tidak baik."}, {"jp": "いよいよ", "meaning_id": "akhirnya, semakin", "penjelasan": "Menyatakan sesuatu akhirnya terjadi setelah dinanti, atau intensitas meningkat.", "contoh_jp": "いよいよ しけん の ひ です。", "contoh_id": "Akhirnya hari ujian tiba."}, {"jp": "反面", "meaning_id": "di sisi lain", "penjelasan": "Menyatakan aspek berlawanan dari suatu hal.", "contoh_jp": "べんり な はんめん、あぶない です。", "contoh_id": "Praktis, namun di sisi lain berbahaya."}, {"jp": "果たして", "meaning_id": "apakah benar-benar, ternyata memang", "penjelasan": "Menekankan pertanyaan/dugaan yang ingin dipastikan.", "contoh_jp": "はたして せいこう する でしょう か。", "contoh_id": "Apakah benar-benar akan berhasil?"}, {"jp": "以上", "meaning_id": "karena sudah, mengingat", "penjelasan": "Menyatakan alasan berdasarkan fakta yang sudah terjadi.", "contoh_jp": "やくそく した いじょう、まもります。", "contoh_id": "Karena sudah berjanji, saya akan menepatinya."}, {"jp": "以上に", "meaning_id": "lebih dari", "penjelasan": "Menyatakan tingkat melebihi sesuatu.", "contoh_jp": "おもった いじょう に むずかしかった。", "contoh_id": "Lebih sulit dari yang dibayangkan."}, {"jp": "いきなり", "meaning_id": "tiba-tiba", "penjelasan": "Menyatakan sesuatu terjadi secara mendadak tanpa peringatan.", "contoh_jp": "いきなり あめ が ふりだした。", "contoh_id": "Tiba-tiba hujan turun."}, {"jp": "いわゆる", "meaning_id": "yang disebut, yang dikenal sebagai", "penjelasan": "Menandai istilah umum yang dikenal masyarakat.", "contoh_jp": "これ が いわゆる ブラック きぎょう です。", "contoh_id": "Ini yang disebut perusahaan 'black' (eksploitatif)."}, {"jp": "上", "meaning_id": "dari segi, dalam hal", "penjelasan": "Menyatakan sudut pandang atau bidang tertentu.", "contoh_jp": "けんこう じょう の りゆう です。", "contoh_id": "Alasan dari segi kesehatan."}, {"jp": "か～ないかのうちに", "meaning_id": "begitu, tepat saat", "penjelasan": "Menyatakan sesuatu terjadi hampir bersamaan dengan hal lain.", "contoh_jp": "ねた か ねない か の うち に、でんわ が なった。", "contoh_id": "Baru saja mau tidur, telepon berbunyi."}, {"jp": "かえって", "meaning_id": "malah, sebaliknya", "penjelasan": "Menyatakan hasil berlawanan dari yang diharapkan.", "contoh_jp": "くすり を のんだら、かえって わるく なった。", "contoh_id": "Setelah minum obat, malah tambah parah."}, {"jp": "かいがある", "meaning_id": "sepadan, ada hasilnya", "penjelasan": "Menyatakan usaha yang membuahkan hasil setimpal.", "contoh_jp": "どりょく した かい が あった。", "contoh_id": "Usahanya membuahkan hasil."}, {"jp": "か何か", "meaning_id": "atau semacamnya", "penjelasan": "Menyebutkan contoh sambil menyiratkan pilihan lain.", "contoh_jp": "コーヒー か なにか のみますか。", "contoh_id": "Mau minum kopi atau semacamnya?"}, {"jp": "かねない", "meaning_id": "bisa jadi, mungkin saja (negatif)", "penjelasan": "Menyatakan kemungkinan hal buruk terjadi.", "contoh_jp": "じこ を おこしかねません。", "contoh_id": "Bisa saja menyebabkan kecelakaan."}, {"jp": "かねる", "meaning_id": "sulit untuk, tidak bisa", "penjelasan": "Menyatakan ketidakmampuan melakukan sesuatu secara sopan.", "contoh_jp": "おこたえ しかねます。", "contoh_id": "Saya sulit untuk menjawabnya."}, {"jp": "かのよう", "meaning_id": "seolah-olah", "penjelasan": "Menyatakan perumpamaan formal.", "contoh_jp": "しんじつ か の よう に はなす。", "contoh_id": "Berbicara seolah-olah itu kebenaran."}, {"jp": "から言うと", "meaning_id": "dari segi, dilihat dari", "penjelasan": "Menyatakan sudut pandang tertentu.", "contoh_jp": "けいけん から いうと、これ は むずかしい。", "contoh_id": "Dari segi pengalaman, ini sulit."}, {"jp": "からこそ", "meaning_id": "justru karena", "penjelasan": "Menekankan alasan sebagai satu-satunya penyebab.", "contoh_jp": "あなた だから こそ、いえます。", "contoh_id": "Justru karena kamu, saya bisa mengatakannya."}, {"jp": "から見ると", "meaning_id": "dilihat dari", "penjelasan": "Menyatakan penilaian berdasarkan suatu sudut pandang.", "contoh_jp": "この データ から みると、けいざい は かいふく して いる。", "contoh_id": "Dilihat dari data ini, ekonomi sedang pulih."}, {"jp": "からには", "meaning_id": "karena sudah, mengingat", "penjelasan": "Menyatakan tekad berdasarkan fakta yang sudah terjadi.", "contoh_jp": "やる から には、さいご まで がんばります。", "contoh_id": "Karena sudah memulai, saya akan berusaha sampai akhir."}, {"jp": "からして", "meaning_id": "dilihat dari...saja", "penjelasan": "Menekankan satu contoh sebagai bukti untuk kesimpulan umum.", "contoh_jp": "かおいろ から して、げんき じゃ ない よう です。", "contoh_id": "Dilihat dari warna wajahnya saja, sepertinya tidak sehat."}, {"jp": "からすると / からすれば", "meaning_id": "kalau dilihat dari", "penjelasan": "Menyatakan penilaian dari sudut pandang tertentu.", "contoh_jp": "せんもんか から すると、これ は もんだい だ。", "contoh_id": "Kalau dilihat dari sudut pandang ahli, ini masalah."}, {"jp": "からといって", "meaning_id": "meski begitu, hanya karena", "penjelasan": "Menyatakan bahwa suatu alasan tidak cukup untuk kesimpulan tertentu.", "contoh_jp": "やすい から と いって、かう わけ では ない。", "contoh_id": "Meski murah, bukan berarti saya beli."}, {"jp": "かと思ったら / かと思うと", "meaning_id": "baru saja...tiba-tiba", "penjelasan": "Menyatakan perubahan mendadak setelah suatu kejadian singkat.", "contoh_jp": "ないた か と おもったら、わらいだした。", "contoh_id": "Baru saja menangis, tiba-tiba tertawa."}, {"jp": "限り", "meaning_id": "selama, sepanjang", "penjelasan": "Menyatakan batasan kondisi yang berlaku.", "contoh_jp": "わたし の しる かぎり、それ は ただしい。", "contoh_id": "Sepengetahuan saya, itu benar."}, {"jp": "気", "meaning_id": "merasa ingin", "penjelasan": "Menyatakan perasaan/niat, sering dalam bentuk 気がする atau 気になる.", "contoh_jp": "いく き が しません。", "contoh_id": "Tidak merasa ingin pergi."}, {"jp": "っこない", "meaning_id": "tidak mungkin, mustahil", "penjelasan": "Bentuk santai untuk menyatakan sesuatu mustahil terjadi.", "contoh_jp": "かてっこ ない よ。", "contoh_id": "Tidak mungkin menang."}, {"jp": "ことだから", "meaning_id": "karena memang (sifatnya)", "penjelasan": "Menyatakan dugaan berdasarkan sifat/kebiasaan seseorang.", "contoh_jp": "かれ の こと だから、きっと くる でしょう。", "contoh_id": "Karena memang sifatnya begitu, dia pasti akan datang."}, {"jp": "ことから", "meaning_id": "berdasarkan fakta bahwa", "penjelasan": "Menyatakan asal-usul suatu kesimpulan/nama.", "contoh_jp": "この なまえ は、いろ が しろい こと から きて いる。", "contoh_id": "Nama ini berasal dari fakta warnanya putih."}, {"jp": "ことなく", "meaning_id": "tanpa pernah", "penjelasan": "Menyatakan sesuatu tidak pernah terjadi dalam suatu proses.", "contoh_jp": "あきらめる こと なく、つづけました。", "contoh_id": "Terus melanjutkan tanpa pernah menyerah."}, {"jp": "ことになっている", "meaning_id": "sudah dijadwalkan/ditentukan", "penjelasan": "Menyatakan aturan atau rencana yang sudah tetap.", "contoh_jp": "かいぎ は げつようび に ある こと に なって います。", "contoh_id": "Rapat sudah dijadwalkan hari Senin."}, {"jp": "ことにはならない", "meaning_id": "bukan berarti", "penjelasan": "Menyatakan suatu fakta tidak otomatis menyebabkan kesimpulan tertentu.", "contoh_jp": "それ で かいけつ した こと には なりません。", "contoh_id": "Itu bukan berarti masalahnya sudah selesai."}, {"jp": "ことは～が", "meaning_id": "memang...tapi", "penjelasan": "Mengakui suatu fakta sambil memberi pengecualian/pertentangan.", "contoh_jp": "わかる こと は わかります が、むずかしい です。", "contoh_id": "Memang saya mengerti, tapi tetap sulit."}, {"jp": "まい", "meaning_id": "tidak akan (tekad)", "penjelasan": "Bentuk formal untuk menyatakan tekad tidak melakukan sesuatu.", "contoh_jp": "にどと しまい。", "contoh_id": "Tidak akan melakukannya lagi."}, {"jp": "まったく～ない", "meaning_id": "sama sekali tidak", "penjelasan": "Penekanan negasi total, lebih formal dari ぜんぜん.", "contoh_jp": "まったく わかりません。", "contoh_id": "Sama sekali tidak mengerti."}, {"jp": "も～ば～も", "meaning_id": "baik...maupun...", "penjelasan": "Menghubungkan dua contoh sejenis untuk penekanan.", "contoh_jp": "おかね も なければ、じかん も ない。", "contoh_id": "Baik uang maupun waktu, tidak ada."}, {"jp": "もかまわず", "meaning_id": "tanpa mempedulikan", "penjelasan": "Menyatakan sesuatu dilakukan tanpa peduli suatu kondisi.", "contoh_jp": "あめ も かまわず、そとで あそんだ。", "contoh_id": "Bermain di luar tanpa mempedulikan hujan."}, {"jp": "ものだから", "meaning_id": "karena, soalnya", "penjelasan": "Memberikan alasan dengan nada penjelasan/pembelaan.", "contoh_jp": "いそがしかった もの だから、いけませんでした。", "contoh_id": "Karena sedang sibuk, saya tidak bisa pergi."}, {"jp": "ものではない", "meaning_id": "seharusnya tidak, bukan sesuatu yang", "penjelasan": "Menyatakan norma umum tentang apa yang seharusnya (tidak) dilakukan.", "contoh_jp": "ひと を ばかにする もの では ない。", "contoh_id": "Seharusnya tidak meremehkan orang."}, {"jp": "ものがある", "meaning_id": "ada sesuatu yang (menyentuh)", "penjelasan": "Menyatakan penilaian/kesan mendalam pembicara.", "contoh_jp": "かんどう する もの が あります。", "contoh_id": "Ada sesuatu yang menyentuh hati."}, {"jp": "ものか", "meaning_id": "mana mungkin! (penolakan kuat)", "penjelasan": "Menyatakan penolakan keras dengan nada retoris.", "contoh_jp": "だれ が しんじる もの か。", "contoh_id": "Mana mungkin ada yang percaya!"}, {"jp": "ものなら", "meaning_id": "kalau bisa", "penjelasan": "Bentuk pengandaian dengan nada menantang/berharap.", "contoh_jp": "できる もの なら、やって みろ。", "contoh_id": "Kalau bisa, coba lakukan."}, {"jp": "ものの", "meaning_id": "meskipun", "penjelasan": "Menyatakan pertentangan formal antara dua fakta.", "contoh_jp": "やくそく した もの の、まもれなかった。", "contoh_id": "Meskipun sudah berjanji, tidak bisa menepatinya."}, {"jp": "もっとも", "meaning_id": "meski demikian, hanya saja", "penjelasan": "Menambahkan pengecualian/catatan setelah pernyataan utama.", "contoh_jp": "いきます。もっとも、じかん が あれば です が。", "contoh_id": "Saya akan pergi. Hanya saja, kalau ada waktu."}, {"jp": "もう少しで", "meaning_id": "hampir saja", "penjelasan": "Menyatakan sesuatu hampir terjadi tetapi tidak jadi.", "contoh_jp": "もう すこし で ころぶ ところ でした。", "contoh_id": "Hampir saja jatuh."}, {"jp": "むしろ", "meaning_id": "lebih baik, malah", "penjelasan": "Menyatakan preferensi lain yang lebih tepat dari yang disebutkan.", "contoh_jp": "むしろ いかない ほう が いい。", "contoh_id": "Lebih baik tidak pergi."}, {"jp": "んだって", "meaning_id": "katanya", "penjelasan": "Bentuk santai untuk menyampaikan informasi dari sumber lain.", "contoh_jp": "かれ、けっこん する んだって。", "contoh_id": "Katanya dia akan menikah."}, {"jp": "中を", "meaning_id": "di tengah (kondisi)", "penjelasan": "Menyatakan sesuatu terjadi di tengah suatu kondisi tertentu.", "contoh_jp": "あめ の なか を あるいた。", "contoh_id": "Berjalan di tengah hujan."}, {"jp": "なお", "meaning_id": "selain itu, lebih lanjut", "penjelasan": "Menambahkan informasi tambahan secara formal.", "contoh_jp": "なお、しめきり は あした です。", "contoh_id": "Selain itu, batas waktunya besok."}, {"jp": "ないではいられない", "meaning_id": "tidak bisa menahan diri", "penjelasan": "Menyatakan dorongan kuat yang tidak bisa dihindari.", "contoh_jp": "わらわないでは いられません。", "contoh_id": "Tidak bisa menahan diri untuk tidak tertawa."}, {"jp": "ないことには～ない", "meaning_id": "kalau tidak...maka tidak akan", "penjelasan": "Menyatakan syarat mutlak untuk suatu hasil.", "contoh_jp": "やってみないことには、わかりません。", "contoh_id": "Kalau tidak dicoba, tidak akan tahu."}, {"jp": "なくはない", "meaning_id": "bukannya tidak ada", "penjelasan": "Menyatakan kemungkinan kecil dengan nada tidak yakin (dua negatif).", "contoh_jp": "きぼう が なく は ない。", "contoh_id": "Bukannya tidak ada harapan."}, {"jp": "なにも～ない", "meaning_id": "tidak perlu (sampai)", "penjelasan": "Menyatakan sesuatu tidak perlu dilakukan sejauh itu.", "contoh_jp": "なにも そんなに おこらなくても。", "contoh_id": "Tidak perlu marah sampai segitunya."}, {"jp": "ねばならない", "meaning_id": "harus", "penjelasan": "Bentuk formal/klasik dari なければならない.", "contoh_jp": "やらねば ならない。", "contoh_id": "Harus dilakukan."}, {"jp": "にあたり", "meaning_id": "pada saat, dalam rangka", "penjelasan": "Menandai momen penting/formal saat suatu tindakan dilakukan.", "contoh_jp": "けっこん する に あたり、りょうしん に あいさつ した。", "contoh_id": "Pada saat akan menikah, memberi salam kepada orang tua."}, {"jp": "に反して", "meaning_id": "berlawanan dengan", "penjelasan": "Menyatakan sesuatu bertentangan dengan harapan/aturan.", "contoh_jp": "よそう に はんして、しっぱい した。", "contoh_id": "Berlawanan dengan perkiraan, ternyata gagal."}, {"jp": "にほかならない", "meaning_id": "tidak lain adalah", "penjelasan": "Menegaskan bahwa sesuatu pasti disebabkan oleh satu hal tertentu.", "contoh_jp": "これ は どりょく の けっか に ほかなりません。", "contoh_id": "Ini tidak lain adalah hasil kerja keras."}, {"jp": "に限って", "meaning_id": "khususnya saat, justru saat", "penjelasan": "Menekankan momen tertentu yang sial/khusus.", "contoh_jp": "いそがしい とき に かぎって、でんわ が なる。", "contoh_id": "Justru saat sibuk, telepon berdering."}, {"jp": "に限らず", "meaning_id": "tidak hanya", "penjelasan": "Menyatakan sesuatu berlaku lebih luas dari yang disebutkan.", "contoh_jp": "にほん に かぎらず、せかいじゅう で にんき です。", "contoh_id": "Tidak hanya di Jepang, populer di seluruh dunia."}, {"jp": "に限る", "meaning_id": "paling baik", "penjelasan": "Menyatakan pilihan terbaik dari suatu kategori.", "contoh_jp": "なつ は ビール に かぎる。", "contoh_id": "Musim panas paling cocok minum bir."}, {"jp": "にかかわる", "meaning_id": "berkaitan dengan", "penjelasan": "Menyatakan sesuatu terkait erat dengan hal penting.", "contoh_jp": "いのち に かかわる もんだい です。", "contoh_id": "Masalah yang berkaitan dengan nyawa."}, {"jp": "にかかわらず", "meaning_id": "terlepas dari, tanpa memandang", "penjelasan": "Menyatakan sesuatu berlaku tanpa dipengaruhi faktor yang disebutkan.", "contoh_jp": "てんき に かかわらず、おこなわれます。", "contoh_id": "Akan tetap dilaksanakan terlepas dari cuaca."}, {"jp": "に決まっている", "meaning_id": "pasti", "penjelasan": "Menyatakan keyakinan sangat tinggi.", "contoh_jp": "かれ が くる に きまって いる。", "contoh_id": "Dia pasti datang."}, {"jp": "に越したことはない", "meaning_id": "lebih baik, tidak ada salahnya", "penjelasan": "Menyatakan sesuatu adalah pilihan terbaik meski bukan wajib.", "contoh_jp": "はやい に こした こと は ない。", "contoh_id": "Lebih cepat lebih baik."}, {"jp": "に応えて", "meaning_id": "sebagai tanggapan atas", "penjelasan": "Menyatakan tindakan sebagai respons terhadap suatu permintaan.", "contoh_jp": "きたい に こたえて、がんばります。", "contoh_id": "Berusaha keras sebagai tanggapan atas harapan."}, {"jp": "に加えて", "meaning_id": "selain itu, ditambah dengan", "penjelasan": "Menambahkan hal lain pada yang sudah disebutkan.", "contoh_jp": "あめ に くわえて、かぜ も つよい。", "contoh_id": "Selain hujan, angin juga kencang."}, {"jp": "に基づいて", "meaning_id": "berdasarkan", "penjelasan": "Menandai dasar/landasan suatu tindakan.", "contoh_jp": "じじつ に もとづいて はなします。", "contoh_id": "Berbicara berdasarkan fakta."}, {"jp": "にもかかわらず", "meaning_id": "meskipun, walaupun begitu", "penjelasan": "Menyatakan hasil berlawanan dengan suatu kondisi.", "contoh_jp": "あめ に も かかわらず、きて くれた。", "contoh_id": "Meskipun hujan, tetap datang."}, {"jp": "に向かって", "meaning_id": "menuju, ke arah", "penjelasan": "Menandai arah pergerakan.", "contoh_jp": "えき に むかって あるいた。", "contoh_id": "Berjalan menuju stasiun."}, {"jp": "に応じて", "meaning_id": "sesuai dengan", "penjelasan": "Menyatakan sesuatu disesuaikan dengan kondisi tertentu.", "contoh_jp": "のうりょく に おうじて しごと を わりあてる。", "contoh_id": "Membagi pekerjaan sesuai kemampuan."}, {"jp": "に際して", "meaning_id": "pada kesempatan, dalam rangka", "penjelasan": "Menandai momen formal saat sesuatu terjadi.", "contoh_jp": "にゅうがく に さいして、あいさつ しました。", "contoh_id": "Pada kesempatan masuk sekolah, memberi sambutan."}, {"jp": "に先立ち", "meaning_id": "sebelum, mendahului", "penjelasan": "Menyatakan sesuatu dilakukan sebelum hal lain sebagai persiapan.", "contoh_jp": "かいぎ に さきだち、しりょう を くばった。", "contoh_id": "Sebelum rapat, membagikan dokumen."}, {"jp": "にしろ / にせよ", "meaning_id": "meskipun, entah...atau", "penjelasan": "Menyatakan hasil tetap sama meski beberapa kemungkinan.", "contoh_jp": "どちら に しろ、きめなければ ならない。", "contoh_id": "Yang manapun, harus tetap memutuskan."}, {"jp": "にしろ～にしろ", "meaning_id": "baik...maupun", "penjelasan": "Menyebutkan dua pilihan yang hasilnya sama.", "contoh_jp": "かつ に しろ まける に しろ、ぜんりょく を つくす。", "contoh_id": "Baik menang maupun kalah, berusaha sekuat tenaga."}, {"jp": "に従って", "meaning_id": "sesuai dengan, seiring", "penjelasan": "Menyatakan sesuatu mengikuti aturan atau perubahan tertentu.", "contoh_jp": "きそく に したがって こうどう します。", "contoh_id": "Bertindak sesuai peraturan."}, {"jp": "にしたら", "meaning_id": "kalau dari sudut pandang", "penjelasan": "Menyatakan penilaian dari sudut pandang seseorang.", "contoh_jp": "こども に したら、それ は たいへん な こと だ。", "contoh_id": "Bagi anak-anak, itu hal yang berat."}, {"jp": "にしても～にしても", "meaning_id": "baik...maupun (tanpa pengecualian)", "penjelasan": "Menyatakan sesuatu berlaku pada semua pilihan yang disebutkan.", "contoh_jp": "いく に しても いかない に しても、れんらく してください。", "contoh_id": "Baik pergi maupun tidak, tolong beri kabar."}, {"jp": "に相違ない", "meaning_id": "pasti, tidak diragukan", "penjelasan": "Bentuk formal untuk menyatakan keyakinan kuat.", "contoh_jp": "かれ の しわざ に そういない。", "contoh_id": "Pasti perbuatan dia."}, {"jp": "に沿って", "meaning_id": "sesuai dengan, mengikuti", "penjelasan": "Menyatakan sesuatu mengikuti garis/pedoman tertentu.", "contoh_jp": "けいかく に そって すすめます。", "contoh_id": "Melanjutkan sesuai rencana."}, {"jp": "に過ぎない", "meaning_id": "hanyalah, tidak lebih dari", "penjelasan": "Menegaskan bahwa sesuatu terbatas hanya sebatas itu.", "contoh_jp": "これ は いちれい に すぎません。", "contoh_id": "Ini hanyalah satu contoh saja."}, {"jp": "にて", "meaning_id": "di, dengan (formal)", "penjelasan": "Bentuk formal dari partikel で.", "contoh_jp": "とうきょう にて かいさい します。", "contoh_id": "Diselenggarakan di Tokyo."}, {"jp": "に伴って", "meaning_id": "seiring dengan, akibat dari", "penjelasan": "Menyatakan dua perubahan terjadi bersamaan.", "contoh_jp": "じんこう の ぞうか に ともなって、じゅうたく が ふえた。", "contoh_id": "Seiring bertambahnya penduduk, perumahan bertambah."}, {"jp": "につけ", "meaning_id": "setiap kali, baik...maupun", "penjelasan": "Menyatakan sesuatu selalu teringat/terjadi dalam berbagai situasi.", "contoh_jp": "これ を みる に つけ、おもいだす。", "contoh_id": "Setiap kali melihat ini, teringat."}, {"jp": "につき", "meaning_id": "per, karena", "penjelasan": "Menandai satuan hitungan, atau memberi alasan formal.", "contoh_jp": "いちにん に つき せんえん です。", "contoh_id": "Seribu yen per orang."}, {"jp": "には", "meaning_id": "untuk, demi", "penjelasan": "Menandai tujuan suatu tindakan.", "contoh_jp": "げんき に なる に は、やすむ こと です。", "contoh_id": "Untuk sembuh, sebaiknya istirahat."}, {"jp": "にわたって", "meaning_id": "selama, sepanjang (rentang luas)", "penjelasan": "Menyatakan sesuatu berlangsung dalam rentang waktu/tempat yang luas.", "contoh_jp": "さんじかん に わたって はなしあった。", "contoh_id": "Berdiskusi selama tiga jam."}, {"jp": "のももっともだ", "meaning_id": "wajar saja", "penjelasan": "Menyatakan sesuatu masuk akal/wajar terjadi.", "contoh_jp": "おこる の も もっとも だ。", "contoh_id": "Wajar saja kalau marah."}, {"jp": "のも当然だ", "meaning_id": "memang seharusnya begitu", "penjelasan": "Menyatakan sesuatu adalah hal yang wajar/alami.", "contoh_jp": "しっぱい する の も とうぜん だ。", "contoh_id": "Memang wajar kalau gagal."}, {"jp": "のもとで", "meaning_id": "di bawah (bimbingan/naungan)", "penjelasan": "Menyatakan sesuatu berlangsung di bawah pengaruh/bimbingan tertentu.", "contoh_jp": "せんせい の もとで べんきょう しました。", "contoh_id": "Belajar di bawah bimbingan guru."}, {"jp": "のみならず", "meaning_id": "bukan hanya, tidak hanya", "penjelasan": "Bentuk formal dari だけでなく.", "contoh_jp": "にほん の みならず、せかいじゅう で。", "contoh_id": "Bukan hanya di Jepang, di seluruh dunia."}, {"jp": "抜きで/抜きにして", "meaning_id": "tanpa", "penjelasan": "Menyatakan sesuatu dilakukan tanpa hal yang biasanya disertakan.", "contoh_jp": "じょうだん ぬき で はなしましょう。", "contoh_id": "Ayo bicara tanpa bercanda."}, {"jp": "抜く", "meaning_id": "melakukan hingga tuntas", "penjelasan": "Menyatakan sesuatu diselesaikan hingga akhir meski sulit.", "contoh_jp": "さいご まで はしりぬきました。", "contoh_id": "Berlari hingga tuntas sampai akhir."}, {"jp": "お～願う", "meaning_id": "mohon (sangat sopan)", "penjelasan": "Bentuk permintaan sangat formal.", "contoh_jp": "ごりかい お ねがい します。", "contoh_id": "Mohon dipahami."}, {"jp": "を～として", "meaning_id": "sebagai", "penjelasan": "Menandai peran/fungsi sesuatu.", "contoh_jp": "これ を きねん として おくります。", "contoh_id": "Memberikan ini sebagai kenang-kenangan."}, {"jp": "をこめて", "meaning_id": "dengan penuh (perasaan)", "penjelasan": "Menyatakan sesuatu dilakukan dengan sepenuh hati/perasaan.", "contoh_jp": "あい を こめて つくりました。", "contoh_id": "Dibuat dengan penuh cinta."}, {"jp": "をきっかけに", "meaning_id": "berawal dari, dipicu oleh", "penjelasan": "Menandai peristiwa yang menjadi awal mula suatu perubahan.", "contoh_jp": "この できごと を きっかけ に、へんか した。", "contoh_id": "Berubah, berawal dari kejadian ini."}, {"jp": "を契機に", "meaning_id": "dengan momentum, memanfaatkan kesempatan", "penjelasan": "Mirip をきっかけに, lebih formal.", "contoh_jp": "そつぎょう を けいき に、しゅうしょく しました。", "contoh_id": "Memanfaatkan kelulusan untuk mulai bekerja."}, {"jp": "をめぐって", "meaning_id": "seputar, mengenai (perdebatan)", "penjelasan": "Menandai topik yang menjadi bahan perdebatan/diskusi.", "contoh_jp": "この もんだい を めぐって、ぎろん が つづいている。", "contoh_id": "Perdebatan seputar masalah ini terus berlanjut."}, {"jp": "をもとに", "meaning_id": "berdasarkan, dari dasar", "penjelasan": "Menandai sumber/dasar suatu hal dibuat.", "contoh_jp": "じつわ を もとに した えいが です。", "contoh_id": "Film yang dibuat berdasarkan kisah nyata."}, {"jp": "を除いて", "meaning_id": "kecuali", "penjelasan": "Menandai pengecualian.", "contoh_jp": "にちようび を のぞいて、まいにち あいて います。", "contoh_id": "Buka setiap hari, kecuali hari Minggu."}, {"jp": "を問わず", "meaning_id": "tanpa memandang", "penjelasan": "Menyatakan sesuatu berlaku tanpa membedakan faktor tertentu.", "contoh_jp": "けいけん を とわず、おうぼ できます。", "contoh_id": "Bisa melamar tanpa memandang pengalaman."}, {"jp": "を通じて/ を通して", "meaning_id": "melalui, sepanjang", "penjelasan": "Menandai sarana atau rentang waktu yang menyeluruh.", "contoh_jp": "インターネット を つうじて しりました。", "contoh_id": "Mengetahuinya melalui internet."}, {"jp": "おまけに", "meaning_id": "parahnya lagi, ditambah lagi", "penjelasan": "Menambahkan hal buruk lagi pada situasi yang sudah negatif.", "contoh_jp": "あめ が ふって、おまけに かぜ も つよい。", "contoh_id": "Hujan turun, ditambah lagi angin kencang."}, {"jp": "恐れがある", "meaning_id": "ada kekhawatiran, berpotensi", "penjelasan": "Menyatakan potensi risiko/bahaya, formal.", "contoh_jp": "たいふう が くる おそれ が あります。", "contoh_id": "Ada kekhawatiran topan akan datang."}, {"jp": "ろくに～ない", "meaning_id": "tidak dengan benar", "penjelasan": "Menyatakan sesuatu tidak dilakukan dengan layak/cukup.", "contoh_jp": "ろくに たべて いません。", "contoh_id": "Tidak makan dengan layak."}, {"jp": "際に", "meaning_id": "pada saat, ketika", "penjelasan": "Bentuk formal dari とき.", "contoh_jp": "でかける さい に、かぎ を かけました。", "contoh_id": "Saat keluar rumah, mengunci pintu."}, {"jp": "幸い", "meaning_id": "untungnya, syukurlah", "penjelasan": "Menyatakan rasa syukur atas hal yang baik terjadi.", "contoh_jp": "さいわい、けが は ありません でした。", "contoh_id": "Untungnya, tidak ada yang terluka."}, {"jp": "さらに", "meaning_id": "lebih lanjut, semakin", "penjelasan": "Menambahkan penekanan atau informasi lebih lanjut.", "contoh_jp": "さらに べんきょう します。", "contoh_id": "Belajar lebih lanjut lagi."}, {"jp": "せいぜい", "meaning_id": "paling banyak, paling-paling", "penjelasan": "Menyatakan batas maksimal yang tidak besar.", "contoh_jp": "せいぜい じゅうにん くらい です。", "contoh_id": "Paling banyak sekitar sepuluh orang."}, {"jp": "せめて", "meaning_id": "setidaknya", "penjelasan": "Menyatakan harapan minimal.", "contoh_jp": "せめて でんわ くらい して。", "contoh_id": "Setidaknya telepon dulu."}, {"jp": "次第", "meaning_id": "segera setelah", "penjelasan": "Menyatakan sesuatu dilakukan segera setelah kondisi terpenuhi.", "contoh_jp": "つきしだい、れんらく します。", "contoh_id": "Segera setelah tiba, akan menghubungi."}, {"jp": "次第だ/ 次第で", "meaning_id": "tergantung pada", "penjelasan": "Menyatakan hasil bergantung pada suatu faktor.", "contoh_jp": "てんき しだい で、ちゅうし します。", "contoh_id": "Tergantung cuaca, akan dibatalkan."}, {"jp": "しかも", "meaning_id": "lagipula, dan lagi", "penjelasan": "Menambahkan informasi lain yang memperkuat.", "contoh_jp": "やすくて、しかも おいしい。", "contoh_id": "Murah, dan lagi enak."}, {"jp": "したがって", "meaning_id": "oleh karena itu", "penjelasan": "Menghubungkan sebab dengan akibat secara formal.", "contoh_jp": "あめ です。したがって、ちゅうし します。", "contoh_id": "Sedang hujan. Oleh karena itu, dibatalkan."}, {"jp": "その上", "meaning_id": "selain itu, lagipula", "penjelasan": "Menambahkan informasi tambahan.", "contoh_jp": "やすい し、そのうえ べんり です。", "contoh_id": "Murah, selain itu praktis."}, {"jp": "それなのに", "meaning_id": "padahal begitu", "penjelasan": "Menyatakan pertentangan dengan nada kecewa.", "contoh_jp": "やくそく した。それ なのに、こなかった。", "contoh_id": "Sudah berjanji. Padahal begitu, dia tidak datang."}, {"jp": "それなら", "meaning_id": "kalau begitu", "penjelasan": "Menghubungkan berdasarkan informasi yang baru diberikan lawan bicara.", "contoh_jp": "それ なら、あした いきましょう。", "contoh_id": "Kalau begitu, ayo pergi besok."}, {"jp": "それにしても", "meaning_id": "meskipun begitu", "penjelasan": "Mengakui suatu fakta sambil menambahkan komentar.", "contoh_jp": "それ に して も、たかい です ね。", "contoh_id": "Meskipun begitu, mahal juga ya."}, {"jp": "それとも", "meaning_id": "atau (pilihan)", "penjelasan": "Menghubungkan dua kalimat tanya sebagai pilihan.", "contoh_jp": "バス で いきます か。それとも、あるいて いきます か。", "contoh_id": "Naik bus? Atau jalan kaki?"}, {"jp": "そういえば", "meaning_id": "ngomong-ngomong, jadi ingat", "penjelasan": "Mengalihkan topik berdasarkan sesuatu yang teringat.", "contoh_jp": "そう いえば、かれ は どう して います か。", "contoh_id": "Ngomong-ngomong, bagaimana kabar dia?"}, {"jp": "そうにない", "meaning_id": "sepertinya tidak akan", "penjelasan": "Menyatakan dugaan kuat bahwa sesuatu tidak akan terjadi.", "contoh_jp": "まにあいそう に ない。", "contoh_id": "Sepertinya tidak akan sempat."}, {"jp": "そうすると", "meaning_id": "kalau begitu, dengan begitu", "penjelasan": "Menyatakan akibat logis dari suatu tindakan.", "contoh_jp": "そう すると、じかん が たりません。", "contoh_id": "Kalau begitu, waktunya tidak cukup."}, {"jp": "少しも～ない", "meaning_id": "sedikit pun tidak", "penjelasan": "Penekanan negasi kuat.", "contoh_jp": "すこし も こわく ない。", "contoh_id": "Sedikit pun tidak takut."}, {"jp": "すなわち", "meaning_id": "yaitu, dengan kata lain", "penjelasan": "Menjelaskan ulang dengan istilah lain, formal.", "contoh_jp": "にほん、すなわち にっぽん です。", "contoh_id": "Nihon, yaitu Nippon."}, {"jp": "たあげく", "meaning_id": "akhirnya (setelah lama)", "penjelasan": "Menyatakan hasil akhir setelah proses panjang, sering negatif.", "contoh_jp": "なやんだ あげく、あきらめました。", "contoh_id": "Setelah lama bimbang, akhirnya menyerah."}, {"jp": "直ちに", "meaning_id": "segera, seketika", "penjelasan": "Kata keterangan formal untuk 'segera'.", "contoh_jp": "ただちに たいひなん して ください。", "contoh_id": "Tolong segera mengungsi."}, {"jp": "たまえ", "meaning_id": "lakukanlah (perintah, senior ke junior)", "penjelasan": "Perintah santai dari atasan/senior laki-laki.", "contoh_jp": "がんばり たまえ。", "contoh_id": "Berusahalah!"}, {"jp": "た末 / の末", "meaning_id": "pada akhirnya (setelah proses)", "penjelasan": "Menyatakan hasil akhir setelah proses panjang.", "contoh_jp": "ながい かんがえ の すえ、けつだん しました。", "contoh_id": "Setelah lama berpikir, akhirnya mengambil keputusan."}, {"jp": "たって", "meaning_id": "meskipun, sekalipun", "penjelasan": "Bentuk santai dari ても.", "contoh_jp": "なんど いった たって、きかない。", "contoh_id": "Meski dikatakan berkali-kali, tetap tidak dengar."}, {"jp": "てばかりはいられない", "meaning_id": "tidak bisa terus-menerus", "penjelasan": "Menyatakan sesuatu tidak bisa terus dilakukan.", "contoh_jp": "なげいて ばかり は いられません。", "contoh_id": "Tidak bisa terus-menerus meratap."}, {"jp": "てでも", "meaning_id": "sekalipun harus", "penjelasan": "Menekankan tekad kuat meski harus melakukan sesuatu yang berat.", "contoh_jp": "むり を してでも、いきます。", "contoh_id": "Sekalipun harus memaksakan diri, saya akan pergi."}, {"jp": "て以来", "meaning_id": "sejak", "penjelasan": "Menandai titik awal suatu keadaan yang berlanjut.", "contoh_jp": "にほん に きて いらい、ずっと べんきょう して います。", "contoh_id": "Sejak datang ke Jepang, terus belajar."}, {"jp": "ていては", "meaning_id": "kalau terus-menerus", "penjelasan": "Menyatakan akibat buruk jika suatu kebiasaan diteruskan.", "contoh_jp": "そんなに たべて いては、ふとります よ。", "contoh_id": "Kalau terus makan seperti itu, akan gemuk lho."}, {"jp": "てからでないと", "meaning_id": "kalau belum...maka tidak bisa", "penjelasan": "Menyatakan syarat mutlak yang harus dipenuhi lebih dulu.", "contoh_jp": "しゅくだい を して から でないと、あそべません。", "contoh_id": "Kalau belum mengerjakan PR, tidak boleh bermain."}, {"jp": "てこそ", "meaning_id": "justru dengan", "penjelasan": "Menekankan bahwa hasil hanya mungkin dengan tindakan tertentu.", "contoh_jp": "どりょく してこそ、せいこう する。", "contoh_id": "Justru dengan berusaha, baru bisa berhasil."}, {"jp": "手前", "meaning_id": "karena (demi menjaga muka)", "penjelasan": "Menyatakan alasan bertindak demi menjaga harga diri/reputasi.", "contoh_jp": "やくそく した てまえ、やめられない。", "contoh_id": "Karena sudah berjanji, tidak bisa berhenti."}, {"jp": "てならない", "meaning_id": "sangat, tak tertahankan", "penjelasan": "Menekankan perasaan yang sangat kuat.", "contoh_jp": "しんぱい で ならない。", "contoh_id": "Sangat khawatir."}, {"jp": "てしょうがない", "meaning_id": "sangat, tidak tertahankan", "penjelasan": "Sinonim てたまらない, penekanan perasaan kuat, bentuk santai.", "contoh_jp": "ねむくて しょうがない。", "contoh_id": "Mengantuk sekali."}, {"jp": "てたまらない", "meaning_id": "sangat, tak tertahankan", "penjelasan": "Menekankan perasaan/keadaan yang sangat intens.", "contoh_jp": "のどが かわいて たまらない。", "contoh_id": "Sangat haus sekali."}, {"jp": "て当然だ", "meaning_id": "sudah sewajarnya", "penjelasan": "Menyatakan sesuatu adalah hal yang wajar terjadi.", "contoh_jp": "おこられて とうぜん だ。", "contoh_id": "Sudah sewajarnya dimarahi."}, {"jp": "ては", "meaning_id": "kalau terus, setiap kali", "penjelasan": "Menyatakan pengulangan atau akibat berulang dari suatu tindakan.", "contoh_jp": "たべては ねる せいかつ。", "contoh_id": "Kehidupan yang hanya makan lalu tidur."}, {"jp": "てはいられない", "meaning_id": "tidak bisa terus", "penjelasan": "Menyatakan sesuatu tidak bisa dibiarkan berlanjut.", "contoh_jp": "ゆっくり しては いられません。", "contoh_id": "Tidak bisa santai terus."}, {"jp": "てはならない", "meaning_id": "tidak boleh", "penjelasan": "Larangan formal.", "contoh_jp": "わすれて は なりません。", "contoh_id": "Tidak boleh lupa."}, {"jp": "と同時に", "meaning_id": "bersamaan dengan", "penjelasan": "Menyatakan dua hal terjadi pada waktu yang sama.", "contoh_jp": "そつぎょう と どうじ に、しゅうしょく しました。", "contoh_id": "Bersamaan dengan lulus, langsung bekerja."}, {"jp": "というふうに", "meaning_id": "dengan cara seperti", "penjelasan": "Menyatakan cara/metode tertentu.", "contoh_jp": "こういう ふう に かんがえて ください。", "contoh_id": "Tolong berpikir dengan cara seperti ini."}, {"jp": "ということは", "meaning_id": "berarti", "penjelasan": "Menyimpulkan makna dari suatu informasi.", "contoh_jp": "という こと は、しっぱい した の ですか。", "contoh_id": "Berarti, apakah gagal?"}, {"jp": "というものだ", "meaning_id": "itulah yang disebut", "penjelasan": "Menegaskan definisi/hakikat suatu hal.", "contoh_jp": "これ が じんせい と いう もの だ。", "contoh_id": "Inilah yang disebut kehidupan."}, {"jp": "というものでもない", "meaning_id": "belum tentu juga", "penjelasan": "Mengoreksi anggapan berlebihan.", "contoh_jp": "たかい から いい と いう もの でも ない。", "contoh_id": "Mahal belum tentu bagus juga."}, {"jp": "といった", "meaning_id": "seperti", "penjelasan": "Memberikan contoh spesifik.", "contoh_jp": "すし や てんぷら と いった にほんりょうり。", "contoh_id": "Masakan Jepang seperti sushi dan tempura."}, {"jp": "とか", "meaning_id": "katanya (kurang yakin)", "penjelasan": "Menyampaikan informasi tidak langsung dengan nada kurang yakin.", "contoh_jp": "あした あめ だ とか。", "contoh_id": "Katanya besok hujan."}, {"jp": "と考えられる", "meaning_id": "bisa dianggap, diperkirakan", "penjelasan": "Menyatakan opini/dugaan secara formal dan objektif.", "contoh_jp": "げんいん は これ だ と かんがえられる。", "contoh_id": "Diperkirakan penyebabnya adalah ini."}, {"jp": "ところだった", "meaning_id": "hampir saja", "penjelasan": "Menyatakan sesuatu hampir terjadi tetapi tidak jadi.", "contoh_jp": "あぶない ところ でした。", "contoh_id": "Hampir saja berbahaya."}, {"jp": "ところに/ところへ", "meaning_id": "tepat saat", "penjelasan": "Menyatakan sesuatu terjadi tepat pada momen tertentu.", "contoh_jp": "でかける ところ に、あめ が ふりだした。", "contoh_id": "Tepat saat mau keluar, hujan mulai turun."}, {"jp": "ところを見ると", "meaning_id": "dilihat dari (keadaan)", "penjelasan": "Menyatakan dugaan berdasarkan pengamatan visual.", "contoh_jp": "わらって いる ところ を みると、うまく いった よう だ。", "contoh_id": "Dilihat dari dia tertawa, sepertinya berjalan lancar."}, {"jp": "とっくに", "meaning_id": "sudah dari tadi/dulu", "penjelasan": "Menekankan sesuatu sudah lama terjadi.", "contoh_jp": "とっくに おわりました。", "contoh_id": "Sudah selesai dari tadi."}, {"jp": "とも", "meaning_id": "meskipun, walaupun", "penjelasan": "Bentuk formal untuk menyatakan pertentangan kondisional.", "contoh_jp": "なに が あろう とも、いきます。", "contoh_id": "Apa pun yang terjadi, saya akan pergi."}, {"jp": "としても", "meaning_id": "sekalipun, seandainya", "penjelasan": "Menyatakan hasil tetap sama dalam kondisi hipotetis.", "contoh_jp": "できた と して も、じかん が ない。", "contoh_id": "Sekalipun bisa, tidak ada waktu."}, {"jp": "としては", "meaning_id": "sebagai, untuk ukuran", "penjelasan": "Menyatakan sudut pandang berdasarkan suatu peran/kategori.", "contoh_jp": "がくせい と して は、じゅうぶん です。", "contoh_id": "Untuk ukuran mahasiswa, ini sudah cukup."}, {"jp": "つもりで", "meaning_id": "dengan niat, seolah-olah", "penjelasan": "Menyatakan niat/anggapan saat melakukan sesuatu.", "contoh_jp": "しんだ つもり で がんばります。", "contoh_id": "Berusaha keras seolah-olah sudah mati (habis-habisan)."}, {"jp": "つつ", "meaning_id": "sambil, meski", "penjelasan": "Bentuk formal ながら, bisa juga berarti pertentangan.", "contoh_jp": "わかりつつ、やめられない。", "contoh_id": "Meski tahu, tidak bisa berhenti."}, {"jp": "つつある", "meaning_id": "sedang (proses berubah)", "penjelasan": "Menyatakan perubahan yang sedang berlangsung.", "contoh_jp": "かいぜん しつつ あります。", "contoh_id": "Sedang mengalami perbaikan."}, {"jp": "上で", "meaning_id": "setelah, dalam proses", "penjelasan": "Menyatakan urutan langkah, atau konteks saat melakukan sesuatu.", "contoh_jp": "よく かんがえた うえで、きめました。", "contoh_id": "Setelah berpikir matang-matang, baru memutuskan."}, {"jp": "上に", "meaning_id": "selain itu, ditambah lagi", "penjelasan": "Menambahkan informasi lain yang sejalan.", "contoh_jp": "やすい うえ に、おいしい です。", "contoh_id": "Murah, ditambah lagi enak."}, {"jp": "上は", "meaning_id": "karena sudah, mengingat", "penjelasan": "Menyatakan tekad berdasarkan fakta yang sudah terjadi, formal.", "contoh_jp": "やる と いった うえ は、さいご まで やります。", "contoh_id": "Karena sudah bilang akan melakukan, akan diselesaikan sampai akhir."}, {"jp": "は別として", "meaning_id": "terlepas dari, kecuali", "penjelasan": "Mengesampingkan sesuatu untuk fokus pada hal lain.", "contoh_jp": "かかく は べつ として、しつ は いい です。", "contoh_id": "Terlepas dari harga, kualitasnya bagus."}, {"jp": "はもとより", "meaning_id": "tentu saja, apalagi", "penjelasan": "Menekankan sesuatu sudah pasti, ditambah hal lain juga.", "contoh_jp": "にほんご は もとより、えいご も できます。", "contoh_id": "Bahasa Jepang tentu saja bisa, bahasa Inggris juga bisa."}, {"jp": "はともかく", "meaning_id": "terlepas dari, apapun soal", "penjelasan": "Mengesampingkan sementara suatu topik untuk fokus ke hal lain.", "contoh_jp": "けっか は ともかく、どりょく しました。", "contoh_id": "Terlepas dari hasilnya, sudah berusaha."}, {"jp": "わずかに", "meaning_id": "sedikit sekali", "penjelasan": "Menyatakan jumlah/tingkat yang sangat kecil.", "contoh_jp": "わずかに のこって います。", "contoh_id": "Tersisa sedikit sekali."}, {"jp": "やがて", "meaning_id": "tak lama lagi, akhirnya", "penjelasan": "Menyatakan sesuatu akan terjadi dalam waktu dekat.", "contoh_jp": "やがて はる が くる。", "contoh_id": "Tak lama lagi musim semi akan tiba."}, {"jp": "やら～やら", "meaning_id": "entah...entah (kebingungan)", "penjelasan": "Menyebutkan contoh dengan nada bingung/campur aduk.", "contoh_jp": "うれしい やら かなしい やら。", "contoh_id": "Entah senang entah sedih (perasaan campur aduk)."}, {"jp": "よりほかない", "meaning_id": "tidak ada pilihan selain", "penjelasan": "Menyatakan satu-satunya pilihan yang tersisa.", "contoh_jp": "あきらめる より ほか ない。", "contoh_id": "Tidak ada pilihan selain menyerah."}, {"jp": "ようでは", "meaning_id": "kalau begini terus", "penjelasan": "Menyatakan konsekuensi buruk jika suatu keadaan berlanjut.", "contoh_jp": "この ようでは、まにあわない。", "contoh_id": "Kalau begini terus, tidak akan sempat."}, {"jp": "ようがない/ようもない", "meaning_id": "tidak ada cara untuk", "penjelasan": "Menyatakan sesuatu mustahil dilakukan karena tidak ada caranya.", "contoh_jp": "どうし ようもない。", "contoh_id": "Tidak ada cara lagi (sudah tidak bisa berbuat apa-apa)."}, {"jp": "要するに", "meaning_id": "intinya, singkatnya", "penjelasan": "Merangkum poin utama.", "contoh_jp": "ようするに、じかん が ない と いう こと です。", "contoh_id": "Intinya, tidak ada waktu."}, {"jp": "ざるを得ない", "meaning_id": "terpaksa harus", "penjelasan": "Menyatakan sesuatu terpaksa dilakukan meski tidak ingin.", "contoh_jp": "やめざるを えません。", "contoh_id": "Terpaksa harus berhenti."}, {"jp": "ずに済む", "meaning_id": "bisa tanpa perlu", "penjelasan": "Menyatakan sesuatu berhasil dihindari.", "contoh_jp": "あやまらずに すみました。", "contoh_id": "Bisa selesai tanpa perlu minta maaf."}];
/* ====== TERJEMAHAN INDONESIA — POLA KALIMAT N1 (tahap 5, dari PDF Kumpulan Tata Bahasa JLPT N1) ====== */
const PATTERNS_ID_N1 = [{"jp": "あえて", "meaning_id": "sengaja; berani melakukan sesuatu meskipun ada risiko atau alasan untuk tidak melakukannya.", "penjelasan": "Pola: あえて + 動詞. あえて digunakan ketika seseorang dengan sengaja memilih melakukan sesuatu yang sebenarnya sulit, tidak perlu, atau berlawanan dengan keadaan umum.", "contoh_jp": "彼はみんなが反対する中、あえてその計画を実行した。", "contoh_id": "Di tengah semua orang yang menentangnya, dia justru sengaja menjalankan rencana tersebut."}, {"jp": "あくまでも", "meaning_id": "tetap; semata-mata; sampai akhir; sebatas pada sesuatu.", "penjelasan": "Pola: あくまでも + 名詞 / 動詞. Digunakan untuk menegaskan sikap, pendirian, atau batasan tertentu tanpa mengubah prinsip tersebut.", "contoh_jp": "私はあくまでも自分の意見を述べただけです。", "contoh_id": "Saya hanya menyampaikan pendapat saya sendiri."}, {"jp": "案の定", "meaning_id": "seperti yang diduga; ternyata sesuai dugaan.", "penjelasan": "Pola: 案の定、～。. Digunakan ketika sesuatu benar-benar terjadi sesuai dengan apa yang sebelumnya telah diperkirakan.", "contoh_jp": "案の定、試験の日に彼は遅刻した。", "contoh_id": "Seperti yang sudah diduga, dia terlambat pada hari ujian."}, {"jp": "あらかじめ", "meaning_id": "sebelumnya; terlebih dahulu; di muka.", "penjelasan": "Pola: あらかじめ + 動詞. Digunakan untuk menunjukkan bahwa suatu tindakan dilakukan sebelum sesuatu terjadi sebagai persiapan.", "contoh_jp": "会議に必要な資料をあらかじめ準備しておいてください。", "contoh_id": "Tolong siapkan terlebih dahulu dokumen yang diperlukan untuk rapat."}, {"jp": "～あっての", "meaning_id": "berkat adanya ～; ～lah yang membuat sesuatu menjadi mungkin.", "penjelasan": "Pola: 名詞 + あっての + 名詞. Menunjukkan bahwa sesuatu yang disebut sebelumnya merupakan dasar atau faktor yang sangat penting bagi keberadaan sesuatu yang lain.", "contoh_jp": "お客様あっての会社です。", "contoh_id": "Perusahaan ini ada berkat para pelanggan. Nuansa: Pola ini sering digunakan untuk menyatakan rasa terima kasih atau penghargaan terhadap faktor yang menjadi dasar keberadaan sesuatu."}, {"jp": "場合によっては", "meaning_id": "tergantung situasinya; dalam keadaan tertentu; bergantung pada kasusnya.", "penjelasan": "Pola: 場合によっては、～。. Digunakan ketika hasil atau tindakan berbeda bergantung pada kondisi yang terjadi.", "contoh_jp": "場合によっては、計画を変更する必要があります。", "contoh_id": "Tergantung situasinya, kita mungkin perlu mengubah rencana."}, {"jp": "～ばこそ", "meaning_id": "justru karena; karena memang ～.", "penjelasan": "Pola: 動詞仮定形 + ばこそ. Menekankan bahwa alasan tertentu merupakan penyebab utama atau satu-satunya yang memungkinkan terjadinya sesuatu.", "contoh_jp": "努力すればこそ、成功できたのだ。", "contoh_id": "Justru karena berusaha keraslah, saya bisa berhasil."}, {"jp": "～ばそれまでだ", "meaning_id": "kalau sampai ～, semuanya berakhir; kalau begitu, selesai sudah.", "penjelasan": "Pola: 動詞仮定形 + ば、それまでだ. Digunakan untuk menunjukkan bahwa jika kondisi tertentu terjadi, usaha atau sesuatu yang selama ini dilakukan menjadi sia-sia.", "contoh_jp": "ここで諦めればそれまでだ。", "contoh_id": "Kalau menyerah di sini, semuanya berakhir."}, {"jp": "～べからず", "meaning_id": "dilarang; jangan; tidak boleh.", "penjelasan": "Pola: 動詞辞書形 + べからず. Merupakan bentuk larangan yang sangat formal dan bergaya klasik. Sering ditemukan pada peraturan, papan peringatan, atau tulisan formal.", "contoh_jp": "関係者以外、入るべからず。", "contoh_id": "Selain pihak yang berkepentingan, dilarang masuk."}, {"jp": "～べく", "meaning_id": "demi; untuk; dengan tujuan untuk.", "penjelasan": "Pola: 動詞辞書形 + べく. Menunjukkan tujuan melakukan suatu tindakan. Nuansanya sangat formal dan lebih sering digunakan dalam tulisan.", "contoh_jp": "目標を達成すべく、社員全員が努力している。", "contoh_id": "Demi mencapai target, seluruh karyawan sedang berusaha."}, {"jp": "～べくもない", "meaning_id": "mustahil; tidak mungkin; sama sekali tidak dapat.", "penjelasan": "Pola: 動詞辞書形 + べくもない. Menunjukkan bahwa sesuatu sangat tidak mungkin dilakukan atau dicapai.", "contoh_jp": "彼の才能は私などには比べるべくもない。", "contoh_id": "Bakatnya sama sekali tidak mungkin dibandingkan dengan kemampuan saya."}, {"jp": "～びる", "meaning_id": "tampak seperti; terlihat memiliki sifat ～.", "penjelasan": "Pola: 名詞 / 語幹 + びる. Digunakan untuk menyatakan bahwa seseorang atau sesuatu menunjukkan ciri atau kesan tertentu.", "contoh_jp": "彼は少し大人びた話し方をする。", "contoh_id": "Dia berbicara dengan cara yang agak dewasa."}, {"jp": "～ぶり", "meaning_id": "cara; gaya; keadaan ketika melakukan sesuatu.", "penjelasan": "Pola: 名詞 + ぶり. Digunakan untuk menggambarkan cara atau keadaan seseorang ketika melakukan suatu aktivitas.", "contoh_jp": "彼の仕事ぶりには感心した。", "contoh_id": "Saya kagum melihat cara dia bekerja."}, {"jp": "～ぶる", "meaning_id": "berpura-pura menjadi; bersikap seperti.", "penjelasan": "Pola: 名詞 / ナ形容詞語幹 + ぶる. Menunjukkan bahwa seseorang bertingkah seolah-olah memiliki sifat tertentu, biasanya dengan nuansa negatif.", "contoh_jp": "彼はいつも偉そうにして、知識人ぶっている。", "contoh_id": "Dia selalu bersikap seolah-olah dirinya seorang intelektual."}, {"jp": "～だに", "meaning_id": "bahkan; sekadar ～ saja.", "penjelasan": "Pola: 動詞辞書形 + だに 名詞 + だに. Digunakan untuk sesuatu yang sangat ekstrem sehingga bahkan membayangkan atau melakukan hal tersebut saja sudah luar biasa.", "contoh_jp": "その事故のことは思い出すだに恐ろしい。", "contoh_id": "Bahkan hanya mengingat kecelakaan itu saja sudah menakutkan."}, {"jp": "～だの～だの", "meaning_id": "～ dan ～; seperti ～, ～, dan sebagainya.", "penjelasan": "Pola: ～だの～だの. Digunakan untuk menyebutkan beberapa contoh secara berurutan. Sering memiliki nuansa bahwa pembicara merasa terganggu atau tidak puas.", "contoh_jp": "彼は仕事が忙しいだの、疲れているだのと言っている。", "contoh_id": "Dia mengatakan bahwa pekerjaannya sibuk, dia lelah, dan sebagainya."}, {"jp": "～であれ～であれ", "meaning_id": "baik ～ maupun ～; apakah ～ ataupun ～.", "penjelasan": "Pola: 名詞 + であれ + 名詞 + であれ. Menunjukkan bahwa hasil atau keadaan tidak berubah meskipun kondisinya berbeda.", "contoh_jp": "子供であれ大人であれ、ルールを守らなければならない。", "contoh_id": "Baik anak-anak maupun orang dewasa harus mematuhi aturan."}, {"jp": "～であれ / ～であろうと", "meaning_id": "siapa pun; apa pun; bagaimanapun keadaannya.", "penjelasan": "Pola: 名詞 + であれ 名詞 + であろうと. Digunakan untuk mengatakan bahwa sesuatu tetap berlaku tanpa memandang siapa, apa, atau bagaimana kondisinya.", "contoh_jp": "どんな理由であろうと、暴力は許されない。", "contoh_id": "Apa pun alasannya, kekerasan tidak dapat dibenarkan."}, {"jp": "～でも何でもない", "meaning_id": "sama sekali bukan ～; tidak sedikit pun ～.", "penjelasan": "Pola: 名詞 + でも何でもない. Digunakan untuk menyangkal sesuatu dengan sangat kuat.", "contoh_jp": "彼は特別な人でも何でもない。", "contoh_id": "Dia sama sekali bukan orang yang istimewa."}, {"jp": "～でなくてなんだろう", "meaning_id": "kalau bukan ～, lalu apa lagi?; pasti ～.", "penjelasan": "Pola: 名詞 + でなくてなんだろう. Merupakan bentuk retoris untuk menekankan keyakinan pembicara bahwa sesuatu pasti merupakan hal tertentu.", "contoh_jp": "これが愛でなくてなんだろう。", "contoh_id": "Kalau ini bukan cinta, lalu apa lagi? Nuansa: Dalam bahasa Indonesia sering diterjemahkan sebagai “ini jelas merupakan cinta”."}, {"jp": "～ではあるまいか", "meaning_id": "bukankah ～?; mungkin ～; saya rasa ～.", "penjelasan": "Pola: 普通形 + のではあるまいか. Digunakan untuk mengemukakan dugaan atau pendapat secara hati-hati, tetapi tetap dengan keyakinan tertentu.", "contoh_jp": "これは何かの間違いではあるまいか。", "contoh_id": "Bukankah ini mungkin sebuah kesalahan?"}, {"jp": "～ではあるまいし", "meaning_id": "bukan berarti ～; ini bukan seperti ～.", "penjelasan": "Pola: 名詞 + ではあるまいし 動詞普通形 + のではあるまいし. Digunakan untuk mengatakan bahwa situasi sekarang tidak sama dengan keadaan tertentu yang dijadikan alasan pembanding.", "contoh_jp": "子供ではあるまいし、自分のことは自分で決めなさい。", "contoh_id": "Kamu bukan anak kecil, jadi tentukan sendiri urusanmu."}, {"jp": "～ではすまない", "meaning_id": "tidak cukup hanya dengan ～; tidak akan selesai hanya dengan ～.", "penjelasan": "Pola: 名詞 + ではすまない 動詞普通形 + ではすまない. Menunjukkan bahwa situasi tersebut terlalu serius sehingga tidak dapat diselesaikan hanya dengan tindakan sederhana.", "contoh_jp": "会社のお金を盗んだのだから、謝るだけではすまない。", "contoh_id": "Karena telah mencuri uang perusahaan, masalah ini tidak akan selesai hanya dengan meminta maaf."}, {"jp": "どうにも～ない", "meaning_id": "sama sekali tidak bisa; bagaimanapun juga tidak dapat.", "penjelasan": "Pola: どうにも + 動詞ない形. Menunjukkan bahwa meskipun sudah mencoba berbagai cara, sesuatu tetap tidak dapat dilakukan atau diatasi.", "contoh_jp": "この問題はどうにも解決できない。", "contoh_id": "Masalah ini benar-benar tidak dapat diselesaikan dengan cara apa pun."}, {"jp": "～がてら", "meaning_id": "sambil; sekaligus; sekalian.", "penjelasan": "Pola: 名詞 + がてら 動詞ます形語幹 + がてら. Digunakan ketika melakukan satu kegiatan sambil memanfaatkan kesempatan tersebut untuk melakukan kegiatan lain.", "contoh_jp": "散歩がてら、コンビニに寄ってきた。", "contoh_id": "Sekalian berjalan-jalan, saya mampir ke minimarket."}, {"jp": "～が早いか", "meaning_id": "segera setelah; begitu ～ langsung ～.", "penjelasan": "Pola: 動詞辞書形 + が早いか. Menunjukkan bahwa tindakan kedua terjadi tepat setelah tindakan pertama. Biasanya digunakan untuk kejadian yang berlangsung sangat cepat.", "contoh_jp": "先生が教室に入るが早いか、学生たちは質問を始めた。", "contoh_id": "Begitu guru masuk kelas, para siswa langsung mulai bertanya."}, {"jp": "～が最後", "meaning_id": "begitu ～, maka; sekali ～ terjadi, maka akan ～.", "penjelasan": "Pola: 動詞た形 + が最後. Menunjukkan bahwa setelah suatu tindakan terjadi, akibat tertentu akan terus berlangsung atau sulit dihentikan.", "contoh_jp": "彼はゲームを始めたが最後、何時間でもやめようとしない。", "contoh_id": "Begitu mulai bermain game, dia tidak mau berhenti selama berjam-jam."}, {"jp": "～ごとき / ～ごとく", "meaning_id": "seperti; sebagaimana; seolah-olah.", "penjelasan": "Pola: 名詞 + のごとき + 名詞 動詞普通形 + かのごとく. Digunakan untuk menyatakan perbandingan atau kesamaan. Merupakan bentuk formal dan sering ditemukan dalam tulisan.", "contoh_jp": "彼は何も知らないかのごとく、平然としていた。", "contoh_id": "Dia bersikap tenang seolah-olah tidak mengetahui apa pun."}, {"jp": "～ぐるみ", "meaning_id": "bersama seluruh ～; melibatkan seluruh ～.", "penjelasan": "Pola: 名詞 + ぐるみ. Menunjukkan bahwa seluruh anggota atau bagian dari suatu kelompok ikut terlibat.", "contoh_jp": "家族ぐるみでその人を支援している。", "contoh_id": "Seluruh keluarga bersama-sama mendukung orang tersebut."}, {"jp": "～羽目になる", "meaning_id": "akhirnya terpaksa mengalami; akhirnya berada dalam situasi yang tidak menyenangkan.", "penjelasan": "Pola: 動詞辞書形 / ない形 + 羽目になる. Digunakan ketika seseorang berakhir dalam situasi buruk atau tidak diinginkan akibat suatu kejadian atau keputusan.", "contoh_jp": "電車に乗り遅れて、タクシーで帰る羽目になった。", "contoh_id": "Karena ketinggalan kereta, akhirnya saya terpaksa pulang dengan taksi."}, {"jp": "～ひとつ", "meaning_id": "mencoba melakukan ～; sebagai satu upaya untuk ～.", "penjelasan": "Pola: 動詞て形 + みる + ひとつ ～ひとつ + ～してみる. Dalam pola N1 ini, ～ひとつ digunakan untuk mengusulkan atau mencoba melakukan sesuatu sebagai sebuah usaha.", "contoh_jp": "ここはひとつ、私に任せてみてください。", "contoh_id": "Untuk kali ini, coba serahkan saja kepada saya."}, {"jp": "～ほどのことはない", "meaning_id": "tidak perlu sampai ～; tidak terlalu penting sampai harus ～.", "penjelasan": "Pola: 動詞辞書形 + ほどのことはない. Digunakan untuk menyatakan bahwa sesuatu tidak cukup serius atau penting untuk dilakukan secara berlebihan.", "contoh_jp": "わざわざ謝るほどのことはない。", "contoh_id": "Tidak perlu sampai repot-repot meminta maaf."}, {"jp": "～ほかに～ない", "meaning_id": "tidak ada pilihan lain selain ～; tidak ada yang lain selain ～.", "penjelasan": "Pola: 動詞辞書形 + ほかに～ない. Menunjukkan bahwa hanya ada satu pilihan atau kemungkinan yang tersisa.", "contoh_jp": "今は待つほかに方法がない。", "contoh_id": "Sekarang tidak ada cara lain selain menunggu."}, {"jp": "～ほうがましだ", "meaning_id": "lebih baik ～; saya lebih memilih ～.", "penjelasan": "Pola: 動詞た形 / ない形 + ほうがましだ. Digunakan ketika dua pilihan sama-sama tidak ideal, tetapi salah satunya dianggap lebih baik daripada yang lain.", "contoh_jp": "何もしないより、失敗しても挑戦したほうがましだ。", "contoh_id": "Daripada tidak melakukan apa-apa, lebih baik mencoba meskipun gagal."}, {"jp": "いかなる", "meaning_id": "apa pun; jenis apa pun; bagaimanapun.", "penjelasan": "Pola: いかなる + 名詞 + も. Merupakan kata yang sangat formal untuk menunjukkan “apa pun jenis atau bentuknya”.", "contoh_jp": "いかなる理由があっても、暴力は許されない。", "contoh_id": "Apa pun alasannya, kekerasan tidak dapat dibenarkan."}, {"jp": "～いかんでは / ～いかんによっては", "meaning_id": "tergantung pada; bergantung pada hasil atau keadaan ～.", "penjelasan": "Pola: 名詞 + いかんでは 名詞 + いかんによっては. いかん merupakan bentuk formal yang memiliki makna “tergantung pada keadaan/hasil ～”.", "contoh_jp": "試験の結果いかんでは、予定を変更する可能性がある。", "contoh_id": "Tergantung pada hasil ujian, ada kemungkinan jadwal akan diubah."}, {"jp": "～いかんによらず", "meaning_id": "terlepas dari; tanpa memandang; tidak peduli bagaimana ～.", "penjelasan": "Pola: 名詞 + いかんによらず. Menunjukkan bahwa hasil atau aturan tidak berubah terlepas dari kondisi atau hasil tertentu.", "contoh_jp": "理由のいかんによらず、規則を破ってはいけない。", "contoh_id": "Apa pun alasannya, aturan tidak boleh dilanggar. Ringkasan Nuansa Penting Pola                    Makna inti                 Nuansa あえて                     sengaja/berani             memilih sesuatu meski sulit Pola       Makna inti             Nuansa あくまでも      tetap/sebatas          menegaskan pendirian 案の定        sesuai dugaan          hasil sesuai perkiraan あらかじめ      terlebih dahulu        persiapan ～あっての      berkat ～               dasar keberadaan 場合によっては    tergantung situasi     kondisi menentukan hasil ～ばこそ       justru karena          menekankan alasan ～ばそれまでだ    kalau ～, selesai       usaha menjadi sia-sia ～べからず      dilarang               sangat formal ～べく        demi/untuk             tujuan formal ～べくもない     mustahil               tidak mungkin ～びる        tampak seperti         memiliki ciri tertentu ～ぶり        cara/gaya              keadaan ketika melakukan ～ぶる        berpura-pura seperti   biasanya bernuansa negatif ～だに        bahkan/sekadar         sesuatu yang ekstrem ～だの～だの     ～ dan ～                menyebut beberapa contoh ～であれ～であれ   baik A maupun B        kondisi tidak memengaruhi hasil ～であろうと     apa pun/siapa pun      tidak peduli kondisi ～でも何でもない   sama sekali bukan      penyangkalan kuat Pola           Makna inti               Nuansa ～でなくてなんだろ kalau bukan ～, apa penegasan う              lagi? ～ではあるまいか       bukankah ～?              dugaan/pendapat formal ～ではあるまいし       bukan seperti ～          alasan pembanding ～ではすまない        tidak cukup hanya ～      masalah serius どうにも～ない        sama sekali tidak bisa   tidak ada cara ～がてら           sambil/sekalian          dua tujuan dalam satu kesempatan ～が早いか          begitu ～ langsung ～      kejadian sangat cepat ～が最後           begitu ～ maka ～          akibat sulit dihentikan ～ごとき/ごとく       seperti/seolah-olah      perbandingan formal ～ぐるみ           bersama seluruh ～        seluruh kelompok terlibat ～羽目になる         akhirnya terpaksa        hasil tidak menyenangkan ～ひとつ           coba lakukan ～           ajakan/usaha ～ほどのことはない tidak perlu sampai ～          tidak cukup serius ～ほかに～ない        tidak ada selain ～       satu-satunya pilihan memilih yang lebih baik dari dua pilihan ～ほうがましだ        lebih baik ～ buruk いかなる           apa pun                  sangat formal ～いかんでは         tergantung ～             hasil bergantung pada kondisi Pola                    Makna inti             Nuansa ～いかんによらず                terlepas dari ～        kondisi tidak memengaruhi aturan Perbedaan yang Sering Membingungkan ① 場合によっては vs いかんでは 場合によっては lebih umum dan dapat digunakan dalam percakapan. 場合によっては、計画を変更します。 Tergantung situasinya, kami akan mengubah rencana. いかんでは jauh lebih formal dan sering digunakan dalam bahasa tulisan, pengumuman, atau situasi resmi. 結果いかんでは、計画を変更します。 Bergantung pada hasilnya, kami akan mengubah rencana. ② であれ～であれ vs であろうと であれ～であれ biasanya menyebut dua atau lebih kondisi secara konkret. 子供であれ大人であれ、ルールを守るべきだ。 Baik anak-anak maupun orang dewasa harus mematuhi aturan. であろうと lebih luas dan berarti “apa pun/siapa pun/bagaimanapun”. 誰であろうと、ルールを守らなければならない。 Siapa pun itu, harus mematuhi aturan. ③ ～べく vs ～ために Keduanya dapat berarti “untuk/demi”, tetapi nuansanya berbeda. ために → umum dan dapat digunakan dalam percakapan. 日本へ行くために、日本語を勉強している。 Saya belajar bahasa Jepang untuk pergi ke Jepang. べく → formal dan lebih sering muncul dalam tulisan. 日本へ行くべく、日本語を勉強している。 Saya belajar bahasa Jepang demi pergi ke Jepang. ④ ～ぶり vs ～ぶる Keduanya terlihat mirip tetapi fungsinya berbeda. ～ぶり → cara/gaya/keadaan melakukan sesuatu. 彼の仕事ぶりは素晴らしい。 Cara kerjanya luar biasa. ～ぶる → bertingkah seolah-olah memiliki sifat tertentu. 彼は金持ちぶっている。 Dia bertingkah seolah-olah orang kaya. ⑤ ～が早いか vs ～が最後 ～が早いか → fokus pada kecepatan, tindakan kedua terjadi segera setelah tindakan pertama. 帰宅するが早いか、寝てしまった。 Begitu sampai rumah, dia langsung tertidur. ～が最後 → fokus pada akibat setelah tindakan pertama, biasanya sulit dihentikan atau memiliki konsekuensi yang kuat. ゲームを始めたが最後、何時間もやり続ける。 Begitu mulai bermain game, dia akan terus bermain selama berjam-jam. ⑥ ～ほかに～ない vs ～ほうがましだ ほかに～ない → tidak ada pilihan lain. 待つほかにない。 Tidak ada pilihan lain selain menunggu. ほうがましだ → ada dua pilihan, tetapi salah satunya dianggap lebih baik. 待つほうがましだ。 Lebih baik menunggu. Tata Bahasa JLPT N1 — Bagian Lanjutan いかに ～ ずとも"}, {"jp": "いかに", "meaning_id": "bagaimana; betapa; seberapa.", "penjelasan": "Pola: いかに + 形容詞 / 動詞 いかに～ても. いかに merupakan bentuk formal dari どう. Dalam tata bahasa N1, いかに sering digunakan untuk menekankan tingkat atau cara sesuatu, terutama dalam tulisan formal.", "contoh_jp": "いかに努力しても、結果が出ないことがある。", "contoh_id": "Betapapun kerasnya berusaha, terkadang hasilnya tidak terlihat."}, {"jp": "いかにも", "meaning_id": "memang benar; benar-benar; sangat terlihat seperti.", "penjelasan": "Digunakan ketika sesuatu sangat sesuai dengan gambaran atau kesan tertentu. Dapat juga digunakan sebagai jawaban untuk menyatakan persetujuan kuat terhadap sesuatu.", "contoh_jp": "彼はいかにも日本人らしい話し方をする。", "contoh_id": "Cara bicaranya benar-benar terlihat seperti orang Jepang."}, {"jp": "いまだに", "meaning_id": "sampai sekarang; hingga kini; masih.", "penjelasan": "Menunjukkan bahwa keadaan yang seharusnya sudah berubah atau berakhir ternyata masih berlangsung hingga sekarang.", "contoh_jp": "彼はいまだにその事実を認めていない。", "contoh_id": "Sampai sekarang dia masih belum mengakui fakta tersebut."}, {"jp": "いずれにせよ", "meaning_id": "bagaimanapun juga; apa pun keadaannya; dalam hal apa pun.", "penjelasan": "Digunakan ketika terdapat beberapa kemungkinan, tetapi kesimpulan atau tindakan akhirnya tetap sama.", "contoh_jp": "いずれにせよ、今日中に決めなければならない。", "contoh_id": "Bagaimanapun juga, kita harus memutuskannya hari ini."}, {"jp": "～じみた", "meaning_id": "terlihat seperti; menyerupai; terkesan seperti.", "penjelasan": "Pola: 名詞 + じみた + 名詞. Menunjukkan bahwa seseorang atau sesuatu memiliki sifat atau kesan seperti kata benda yang dilekatkan. Sering memiliki nuansa negatif.", "contoh_jp": "彼は子供じみたことを言っている。", "contoh_id": "Dia mengatakan hal-hal yang kekanak-kanakan."}, {"jp": "～限りだ", "meaning_id": "sangat merasa ～; sungguh ～ sekali.", "penjelasan": "Pola: イ形容詞 + 限りだ ナ形容詞 + な + 限りだ. Digunakan untuk mengungkapkan perasaan yang sangat kuat. Biasanya digunakan bersama kata sifat yang menggambarkan emosi.", "contoh_jp": "このような賞をいただき、光栄な限りです。", "contoh_id": "Saya merasa sangat terhormat menerima penghargaan seperti ini."}, {"jp": "～かいもなく", "meaning_id": "meskipun sudah ～; sia-sia meskipun telah berusaha.", "penjelasan": "Pola: 動詞た形 + かいもなく 名詞 + の + かいもなく. Menunjukkan bahwa usaha atau tindakan yang dilakukan ternyata tidak menghasilkan hasil yang diharapkan.", "contoh_jp": "努力したかいもなく、試験に落ちてしまった。", "contoh_id": "Meskipun sudah berusaha, saya tetap gagal dalam ujian."}, {"jp": "～か否か", "meaning_id": "apakah ～ atau tidak.", "penjelasan": "Pola: 普通形 + か否か 名詞 + か否か. Merupakan bentuk sangat formal dari ～かどうか. Banyak ditemukan dalam dokumen resmi dan tulisan akademik.", "contoh_jp": "参加するか否かを早めに決めてください。", "contoh_id": "Tolong segera putuskan apakah akan ikut atau tidak."}, {"jp": "可能性がある", "meaning_id": "ada kemungkinan ～.", "penjelasan": "Pola: 動詞普通形 + 可能性がある 名詞 + の + 可能性がある. Menunjukkan bahwa sesuatu mungkin terjadi, tetapi belum dapat dipastikan.", "contoh_jp": "明日は大雨になる可能性があります。", "contoh_id": "Ada kemungkinan besok akan terjadi hujan deras."}, {"jp": "～からある", "meaning_id": "sebanyak; mencapai sekitar; tidak kurang dari.", "penjelasan": "Pola: 数量 + からある. Digunakan setelah angka atau jumlah untuk menekankan bahwa jumlah tersebut besar atau melebihi perkiraan.", "contoh_jp": "彼は 100 キロからある荷物を一人で運んだ。", "contoh_id": "Dia membawa barang seberat lebih dari 100 kg seorang diri."}, {"jp": "～かれ～かれ", "meaning_id": "entah ～ atau ～; baik ～ maupun ～.", "penjelasan": "Pola: イ形容詞語幹 + かれ + イ形容詞語幹 + かれ. Digunakan untuk menyatakan dua keadaan yang berbeda tetapi hasil akhirnya sama. Biasanya menggunakan bentuk kata sifat.", "contoh_jp": "遅かれ早かれ、彼は真実を知るだろう。", "contoh_id": "Cepat atau lambat, dia akan mengetahui kebenarannya."}, {"jp": "～かたがた", "meaning_id": "sekaligus; sambil; dengan tujuan ～ sekaligus.", "penjelasan": "Pola: 名詞 + かたがた. Digunakan ketika satu kegiatan dilakukan sekaligus untuk tujuan lain. Sangat formal dan sering digunakan dalam situasi resmi.", "contoh_jp": "ご挨拶かたがた、先生のところへ伺いました。", "contoh_id": "Saya mengunjungi tempat guru sekaligus untuk menyampaikan salam."}, {"jp": "～かたわら", "meaning_id": "sambil; di samping; pada saat yang sama.", "penjelasan": "Pola: 動詞辞書形 + かたわら 名詞 + の + かたわら. Menunjukkan bahwa seseorang melakukan dua aktivitas secara paralel dalam jangka waktu tertentu.", "contoh_jp": "彼は会社で働くかたわら、大学で勉強している。", "contoh_id": "Selain bekerja di perusahaan, dia juga belajar di universitas."}, {"jp": "かつて", "meaning_id": "dahulu; pernah; pada masa lalu.", "penjelasan": "Mengacu pada masa lalu yang cukup jauh, biasanya untuk sesuatu yang sudah berubah atau tidak lagi terjadi.", "contoh_jp": "かつてこの町には大きな工場があった。", "contoh_id": "Dahulu, ada sebuah pabrik besar di kota ini."}, {"jp": "～嫌いがある", "meaning_id": "cenderung; memiliki kecenderungan untuk ～.", "penjelasan": "Pola: 動詞辞書形 + 嫌いがある 名詞 + の + 嫌いがある. Menunjukkan kecenderungan yang biasanya bernuansa negatif atau merupakan kelemahan.", "contoh_jp": "彼は物事を深く考えすぎる嫌いがある。", "contoh_id": "Dia cenderung terlalu memikirkan sesuatu secara mendalam."}, {"jp": "～きっての", "meaning_id": "yang paling terkenal/terkemuka di antara ～.", "penjelasan": "Pola: 名詞 + きっての + 名詞. Digunakan untuk menyatakan seseorang atau sesuatu yang dianggap paling unggul atau terkenal dalam suatu kelompok.", "contoh_jp": "彼はこの町きっての有名な料理人だ。", "contoh_id": "Dia adalah koki paling terkenal di kota ini."}, {"jp": "きりがない", "meaning_id": "tidak ada habisnya; tidak ada akhirnya.", "penjelasan": "Digunakan ketika sesuatu terus berlangsung sehingga tidak mungkin selesai jika diteruskan.", "contoh_jp": "文句を言い始めたらきりがない。", "contoh_id": "Kalau mulai mengeluh, tidak akan ada habisnya."}, {"jp": "～極まる / ～極まりない", "meaning_id": "sangat; luar biasa; benar-benar ekstrem.", "penjelasan": "Pola: ナ形容詞語幹 + 極まる ナ形容詞語幹 + 極まりない. Digunakan untuk menunjukkan tingkat yang sangat ekstrem. Umumnya digunakan dengan kata yang menggambarkan perasaan atau penilaian.", "contoh_jp": "彼の行動は無責任極まりない。", "contoh_id": "Tindakannya benar-benar sangat tidak bertanggung jawab."}, {"jp": "極めて", "meaning_id": "sangat; amat; teramat.", "penjelasan": "Kata keterangan formal yang digunakan untuk menunjukkan tingkat yang sangat tinggi.", "contoh_jp": "これは極めて重要な問題です。", "contoh_id": "Ini merupakan masalah yang sangat penting."}, {"jp": "～ことだし", "meaning_id": "karena; lagipula; mengingat bahwa ～.", "penjelasan": "Pola: 普通形 + ことだし. Digunakan ketika memberikan alasan tambahan untuk suatu keputusan atau tindakan.", "contoh_jp": "天気もいいことだし、今日は出かけましょう。", "contoh_id": "Cuacanya juga bagus, jadi hari ini mari kita pergi keluar."}, {"jp": "ことごとく", "meaning_id": "semuanya; seluruhnya; tanpa terkecuali.", "penjelasan": "Menunjukkan bahwa semua hal atau semua anggota dalam suatu kelompok mengalami hal yang sama.", "contoh_jp": "彼の提案はことごとく反対された。", "contoh_id": "Semua usulnya ditentang tanpa terkecuali."}, {"jp": "～ことなしに", "meaning_id": "tanpa melakukan ～.", "penjelasan": "Pola: 動詞辞書形 + ことなしに. Menunjukkan bahwa suatu tindakan dilakukan tanpa terlebih dahulu melakukan tindakan lain. Formal.", "contoh_jp": "努力することなしに成功することはできない。", "contoh_id": "Tidak mungkin berhasil tanpa berusaha."}, {"jp": "～ことのないよう", "meaning_id": "agar tidak ～; supaya jangan sampai ～.", "penjelasan": "Pola: 動詞辞書形 + ことのないよう. Digunakan untuk menunjukkan tujuan agar suatu hal yang tidak diinginkan tidak terjadi.", "contoh_jp": "忘れることのないよう、メモしておいてください。", "contoh_id": "Tolong catat agar tidak lupa."}, {"jp": "～こととて", "meaning_id": "karena; mengingat bahwa ～.", "penjelasan": "Pola: 名詞 + の + こととて 普通形 + こととて. Merupakan pola yang sangat formal dan bernuansa klasik. Digunakan untuk memberikan alasan atau keadaan yang menjadi latar belakang suatu tindakan.", "contoh_jp": "新人のこととて、何かとご迷惑をおかけするかもしれません。", "contoh_id": "Karena saya masih pegawai baru, mungkin saya akan merepotkan Anda dalam berbagai hal."}, {"jp": "～くらいなら", "meaning_id": "daripada ～, lebih baik ～.", "penjelasan": "Pola: 動詞辞書形 + くらいなら、～. Digunakan ketika pembicara lebih memilih pilihan kedua karena pilihan pertama dianggap buruk atau tidak diinginkan.", "contoh_jp": "嘘をつくくらいなら、何も言わないほうがいい。", "contoh_id": "Daripada berbohong, lebih baik tidak mengatakan apa-apa."}, {"jp": "～くらいのものだ", "meaning_id": "hanya ～; paling-paling hanya ～.", "penjelasan": "Menunjukkan bahwa hanya ada sedikit hal yang dapat dilakukan atau terjadi.", "contoh_jp": "私にできるのは、これくらいのものだ。", "contoh_id": "Yang bisa saya lakukan paling hanya sebatas ini."}, {"jp": "～までだ", "meaning_id": "hanya ～; saya hanya akan ～; paling-paling ～.", "penjelasan": "Dalam pola N1 ini, までだ dapat digunakan untuk menunjukkan batas terakhir atau satu- satunya tindakan yang akan dilakukan.", "contoh_jp": "失敗したら、もう一度挑戦するまでだ。", "contoh_id": "Kalau gagal, saya hanya perlu mencoba sekali lagi."}, {"jp": "～までもない", "meaning_id": "tidak perlu sampai ～; tidak perlu melakukan ～.", "penjelasan": "Pola: 動詞辞書形 + までもない. Digunakan untuk menyatakan bahwa suatu tindakan tidak perlu dilakukan karena sudah jelas atau tidak diperlukan.", "contoh_jp": "そんなことは言うまでもない。", "contoh_id": "Hal seperti itu tidak perlu dikatakan lagi."}, {"jp": "～まじき", "meaning_id": "tidak pantas; tidak seharusnya; tidak boleh.", "penjelasan": "Pola: 名詞 + にあるまじき + 名詞 動詞辞書形 + まじき. Digunakan untuk menunjukkan perilaku yang tidak pantas bagi seseorang berdasarkan posisi, status, atau tanggung jawabnya.", "contoh_jp": "教師にあるまじき行為だ。", "contoh_id": "Itu merupakan tindakan yang tidak pantas dilakukan oleh seorang guru."}, {"jp": "～ままに", "meaning_id": "sesuai dengan; mengikuti; sebagaimana adanya.", "penjelasan": "Pola: 動詞辞書形 + ままに 動詞た形 + ままに. Menunjukkan bahwa seseorang melakukan sesuatu sesuai dengan keinginan, instruksi, atau keadaan tertentu tanpa mengubahnya.", "contoh_jp": "自分の思うままに行動してください。", "contoh_id": "Silakan bertindak sesuai dengan keinginan Anda sendiri."}, {"jp": "～まみれ", "meaning_id": "penuh dengan; berlumuran; tertutup oleh.", "penjelasan": "Pola: 名詞 + まみれ. Digunakan ketika sesuatu tertutup atau dipenuhi oleh benda yang biasanya berupa cairan, kotoran, debu, darah, atau sesuatu yang tidak diinginkan.", "contoh_jp": "彼の服は泥まみれになった。", "contoh_id": "Pakaiannya menjadi penuh lumpur."}, {"jp": "まるっきり", "meaning_id": "sama sekali; sepenuhnya.", "penjelasan": "Biasanya digunakan bersama bentuk negatif untuk memberikan penekanan kuat bahwa sesuatu benar-benar tidak ada atau tidak terjadi.", "contoh_jp": "彼の話はまるっきり理解できない。", "contoh_id": "Saya sama sekali tidak memahami perkataannya."}, {"jp": "～めく", "meaning_id": "menunjukkan tanda-tanda; tampak seperti; mulai memiliki kesan ～.", "penjelasan": "Pola: 名詞 + めく. Menunjukkan bahwa sesuatu mulai memperlihatkan ciri atau suasana tertentu.", "contoh_jp": "春めいた暖かい日が続いている。", "contoh_id": "Hari-hari hangat dengan nuansa musim semi terus berlangsung."}, {"jp": "もはや", "meaning_id": "sudah; sekarang sudah; tidak lagi.", "penjelasan": "Menunjukkan bahwa keadaan telah berubah dan sesuatu yang sebelumnya berlaku sekarang sudah tidak berlaku lagi.", "contoh_jp": "彼はもはや以前の彼ではない。", "contoh_id": "Dia sekarang sudah bukan dirinya yang dulu."}, {"jp": "～も顧みず / ～を顧みず", "meaning_id": "tanpa memedulikan; mengabaikan; meskipun mempertaruhkan ～.", "penjelasan": "Pola: 名詞 + を顧みず 名詞 + も顧みず. Digunakan ketika seseorang tetap melakukan sesuatu tanpa memedulikan bahaya, risiko, atau kerugian yang mungkin dialaminya.", "contoh_jp": "彼は自分の安全を顧みず、人を助けた。", "contoh_id": "Tanpa memedulikan keselamatannya sendiri, dia menolong orang lain."}, {"jp": "～もしないで", "meaning_id": "tanpa melakukan bahkan ～; bahkan tidak ～.", "penjelasan": "Pola: 動詞ます形語幹 + もしないで. Digunakan untuk menekankan bahwa seseorang tidak melakukan tindakan yang seharusnya dilakukan, bahkan tindakan tersebut sama sekali tidak dilakukan.", "contoh_jp": "彼は何も言いもしないで帰ってしまった。", "contoh_id": "Dia pulang tanpa mengatakan apa pun sama sekali."}, {"jp": "～もので", "meaning_id": "karena; oleh karena itu.", "penjelasan": "Pola: 普通形 + もので. Digunakan untuk memberikan alasan atau pembenaran, terutama ketika pembicara ingin menjelaskan keadaan yang menyebabkan suatu tindakan.", "contoh_jp": "初めてだったもので、少し緊張しました。", "contoh_id": "Karena ini adalah pertama kalinya bagi saya, saya sedikit gugup."}, {"jp": "～ものを", "meaning_id": "padahal; seandainya; kalau saja.", "penjelasan": "Menunjukkan penyesalan atau ketidakpuasan terhadap keadaan yang sebenarnya bisa berbeda.", "contoh_jp": "もっと早く相談してくれればよかったものを。", "contoh_id": "Padahal seharusnya kamu berkonsultasi lebih awal."}, {"jp": "～ものと思われる", "meaning_id": "diperkirakan; dianggap bahwa; diduga.", "penjelasan": "Pola: 普通形 + ものと思われる. Bentuk formal yang digunakan terutama dalam laporan, berita, tulisan akademik, atau analisis untuk menyatakan suatu dugaan.", "contoh_jp": "今後も物価は上昇するものと思われる。", "contoh_id": "Diperkirakan bahwa harga-harga akan terus meningkat ke depannya."}, {"jp": "～ものとして", "meaning_id": "dengan menganggap bahwa; dengan asumsi bahwa.", "penjelasan": "Pola: 普通形 + ものとして. Digunakan ketika seseorang menetapkan suatu kondisi sebagai asumsi atau dasar untuk tindakan berikutnya.", "contoh_jp": "明日は雨が降るものとして、予定を立てましょう。", "contoh_id": "Mari kita membuat rencana dengan menganggap bahwa besok akan hujan."}, {"jp": "～もさることながら", "meaning_id": "bukan hanya ～, tetapi juga ～; ～ juga tidak kalah penting.", "penjelasan": "Pola: 名詞 + もさることながら. Digunakan untuk mengakui bahwa hal pertama memang penting, tetapi ada hal lain yang juga penting atau lebih menonjol.", "contoh_jp": "この店は料理もさることながら、サービスも素晴らしい。", "contoh_id": "Restoran ini bukan hanya makanannya yang luar biasa, tetapi pelayanannya juga sangat baik."}, {"jp": "もしくは", "meaning_id": "atau; atau jika tidak.", "penjelasan": "Merupakan bentuk formal dari または. Sering ditemukan dalam dokumen, peraturan, kontrak, dan bahasa resmi.", "contoh_jp": "電話もしくはメールでご連絡ください。", "contoh_id": "Silakan hubungi kami melalui telepon atau email."}, {"jp": "～ながらに / ～ながらの", "meaning_id": "dalam keadaan; tetap dalam kondisi ～; sebagaimana adanya.", "penjelasan": "Pola: 名詞 + ながらに 名詞 + ながらの + 名詞. Digunakan untuk menunjukkan bahwa seseorang atau sesuatu tetap berada dalam keadaan tertentu ketika melakukan atau mengalami sesuatu.", "contoh_jp": "彼は涙ながらに自分の経験を語った。", "contoh_id": "Sambil berlinang air mata, dia menceritakan pengalamannya."}, {"jp": "～ないではおかない / ～ずにはおかない", "meaning_id": "pasti akan ～; tidak mungkin tidak ～.", "penjelasan": "Pola: 動詞ない形 + ではおかない 動詞ない形 + ずにはおかない. Menunjukkan bahwa suatu tindakan atau akibat pasti akan terjadi, baik karena kemauan kuat seseorang maupun karena suatu keadaan.", "contoh_jp": "彼の発言は多くの人を怒らせないではおかない。", "contoh_id": "Perkataannya pasti akan membuat banyak orang marah."}, {"jp": "～ないではすまない / ～ずにはすまない", "meaning_id": "harus ～; tidak mungkin tidak melakukan ～.", "penjelasan": "Pola: 動詞ない形 + ではすまない 動詞ない形 + ずにはすまない. Menunjukkan bahwa karena alasan moral, sosial, atau situasi tertentu, seseorang tidak dapat menghindari suatu tindakan.", "contoh_jp": "この問題については、社長に報告しないではすまない。", "contoh_id": "Mengenai masalah ini, kita harus melaporkannya kepada direktur."}, {"jp": "～ないまでも", "meaning_id": "meskipun tidak sampai ～; walaupun tidak melakukan sepenuhnya ～.", "penjelasan": "Pola: 動詞ない形 + までも. Menunjukkan bahwa tingkat yang lebih rendah dari sesuatu sudah cukup atau tetap menghasilkan keadaan tertentu.", "contoh_jp": "毎日とは言わないまでも、週に 3 回は運動したほうがいい。", "contoh_id": "Meskipun tidak harus setiap hari, sebaiknya berolahraga 3 kali seminggu."}, {"jp": "～ないものか", "meaning_id": "tidak bisakah ～?; apakah tidak mungkin ～?", "penjelasan": "Pola: 動詞ない形 + ものか. Digunakan untuk mengungkapkan harapan atau keinginan kuat agar sesuatu terjadi.", "contoh_jp": "もう少し給料を上げてもらえないものか。", "contoh_id": "Tidak bisakah gaji saya dinaikkan sedikit lagi?"}, {"jp": "～ないものでもない", "meaning_id": "bukan berarti mustahil; mungkin saja; tidak sepenuhnya tidak mungkin.", "penjelasan": "Merupakan bentuk negatif ganda yang menunjukkan bahwa sesuatu masih mungkin dilakukan, meskipun tidak mudah atau tidak terlalu yakin.", "contoh_jp": "条件次第では、協力できないものでもない。", "contoh_id": "Tergantung kondisinya, bukan berarti kami sama sekali tidak bisa bekerja sama."}, {"jp": "～ないとも限らない", "meaning_id": "mungkin saja; bukan tidak mungkin.", "penjelasan": "Menunjukkan kemungkinan yang tidak dapat dikesampingkan, meskipun pembicara tidak yakin bahwa hal tersebut benar-benar terjadi.", "contoh_jp": "将来、状況が変わらないとも限らない。", "contoh_id": "Bukan tidak mungkin situasinya berubah di masa depan."}, {"jp": "～なくして", "meaning_id": "tanpa ～; jika tidak ada ～.", "penjelasan": "Pola: 名詞 + なくして. Merupakan bentuk formal yang menekankan bahwa sesuatu tidak mungkin terjadi tanpa adanya faktor tertentu.", "contoh_jp": "努力なくして成功はありえない。", "contoh_id": "Tanpa usaha, keberhasilan tidak mungkin terjadi."}, {"jp": "何しろ", "meaning_id": "bagaimanapun juga; terutama karena; maklum saja.", "penjelasan": "Digunakan untuk memberikan alasan yang dianggap paling penting atau paling kuat.", "contoh_jp": "何しろ初めての経験なので、緊張しています。", "contoh_id": "Maklum saja, karena ini pengalaman pertama saya, jadi saya gugup."}, {"jp": "～なしに", "meaning_id": "tanpa ～.", "penjelasan": "Pola: 名詞 + なしに 動詞辞書形 + ことなしに. Menunjukkan bahwa suatu tindakan dilakukan tanpa adanya sesuatu yang biasanya diperlukan.", "contoh_jp": "許可なしにこの部屋に入ってはいけない。", "contoh_id": "Tidak boleh masuk ruangan ini tanpa izin."}, {"jp": "～ならでは", "meaning_id": "khas ～; hanya bisa dilakukan oleh ～.", "penjelasan": "Pola: 名詞 + ならではの + 名詞. Menunjukkan keunikan atau keistimewaan yang hanya dimiliki oleh seseorang, tempat, kelompok, atau sesuatu tertentu.", "contoh_jp": "京都ならではの美しい景色を楽しんだ。", "contoh_id": "Saya menikmati pemandangan indah yang khas Kyoto."}, {"jp": "～ならいざしらず", "meaning_id": "kalau A mungkin lain cerita, tetapi B ～.", "penjelasan": "Pola: 名詞 + ならいざしらず. Digunakan untuk membuat perbandingan atau pengecualian. Pembicara mengatakan bahwa kondisi A masih dapat dimaklumi, tetapi kondisi B tidak dapat diterima.", "contoh_jp": "子供ならいざしらず、大人がそんなことをするなんて。", "contoh_id": "Kalau anak-anak mungkin masih bisa dimaklumi, tetapi orang dewasa melakukan hal seperti itu sungguh tidak masuk akal."}, {"jp": "～なり", "meaning_id": "segera setelah.", "penjelasan": "Pola: 動詞辞書形 + なり. Menunjukkan bahwa tindakan kedua terjadi segera setelah tindakan pertama, tanpa jeda berarti.", "contoh_jp": "彼は家に帰るなり、ベッドに倒れ込んだ。", "contoh_id": "Begitu sampai rumah, dia langsung menjatuhkan diri ke tempat tidur."}, {"jp": "～なり～なり", "meaning_id": "entah ～ atau ～; misalnya ～ atau ～.", "penjelasan": "Pola: 動詞辞書形 + なり + 動詞辞書形 + なり 名詞 + なり + 名詞 + なり. Digunakan untuk memberikan beberapa pilihan atau contoh.", "contoh_jp": "分からないことがあれば、先生なり友達なりに聞いてください。", "contoh_id": "Kalau ada sesuatu yang tidak dipahami, tanyakan kepada guru atau teman, misalnya."}, {"jp": "～なりに / ～なりの", "meaning_id": "dengan caranya sendiri; sesuai dengan kemampuan atau keadaan seseorang.", "penjelasan": "Menunjukkan bahwa seseorang melakukan sesuatu dengan cara yang sesuai dengan kemampuan, posisi, atau keadaannya sendiri.", "contoh_jp": "私なりに一生懸命考えました。", "contoh_id": "Saya sudah memikirkannya dengan sungguh-sungguh dengan cara saya sendiri."}, {"jp": "～なりとも", "meaning_id": "sedikit saja; setidaknya; walaupun hanya ～.", "penjelasan": "Digunakan untuk meminta atau mengusulkan jumlah yang sangat sedikit sebagai batas minimum.", "contoh_jp": "少しなりともお役に立てれば幸いです。", "contoh_id": "Saya akan senang jika bisa membantu meskipun hanya sedikit."}, {"jp": "～に値する", "meaning_id": "layak untuk; pantas untuk; bernilai untuk.", "penjelasan": "Pola: 名詞 + に値する 動詞辞書形 + に値する. Menunjukkan bahwa sesuatu memiliki nilai atau kualitas yang cukup untuk mendapatkan suatu penilaian/tindakan.", "contoh_jp": "この作品は高く評価するに値する。", "contoh_id": "Karya ini layak mendapatkan penilaian yang tinggi."}, {"jp": "～にあたらない", "meaning_id": "tidak perlu; tidak layak untuk; tidak perlu sampai ～.", "penjelasan": "Digunakan ketika sesuatu tidak cukup penting atau serius sehingga tidak perlu dilakukan.", "contoh_jp": "そんな小さな失敗は驚くにあたらない。", "contoh_id": "Kegagalan kecil seperti itu tidak perlu sampai membuat kita terkejut."}, {"jp": "～にあって", "meaning_id": "dalam; pada kondisi; di tengah situasi ～.", "penjelasan": "Pola: 名詞 + にあって. Digunakan untuk menyatakan situasi, kondisi, atau lingkungan tertentu, terutama dalam bahasa formal.", "contoh_jp": "厳しい状況にあっても、彼は努力を続けた。", "contoh_id": "Meskipun berada dalam situasi yang sulit, dia terus berusaha."}, {"jp": "～にひきかえ", "meaning_id": "berbeda dengan; berlawanan dengan.", "penjelasan": "Pola: 名詞 + にひきかえ. Digunakan untuk menunjukkan kontras yang jelas antara dua hal.", "contoh_jp": "兄の成績が良いのにひきかえ、弟はあまり勉強しない。", "contoh_id": "Berbeda dengan kakaknya yang nilainya bagus, adiknya tidak terlalu rajin belajar."}, {"jp": "～に至るまで", "meaning_id": "sampai pada; hingga; bahkan sampai ～.", "penjelasan": "Menunjukkan rentang yang sangat luas sampai batas tertentu, termasuk hal yang mungkin dianggap ekstrem.", "contoh_jp": "服装から言葉遣いに至るまで、厳しく指導された。", "contoh_id": "Saya dibimbing dengan ketat mulai dari pakaian hingga cara berbicara."}, {"jp": "～に至っては", "meaning_id": "kalau sudah sampai pada ～; khusus mengenai ～.", "penjelasan": "Digunakan ketika pembicara menyoroti satu hal yang dianggap sangat menonjol, ekstrem, atau berbeda dari yang lainnya.", "contoh_jp": "兄も勉強しないが、弟に至っては全く勉強しない。", "contoh_id": "Kakaknya juga tidak belajar, tetapi kalau adiknya, bahkan sama sekali tidak belajar."}, {"jp": "～に言わせれば", "meaning_id": "menurut pendapat ～; kalau ditanya kepada ～.", "penjelasan": "Digunakan untuk menyatakan pendapat seseorang dari sudut pandangnya.", "contoh_jp": "私に言わせれば、その計画には問題が多い。", "contoh_id": "Kalau menurut saya, rencana itu memiliki banyak masalah."}, {"jp": "～にかかっている", "meaning_id": "bergantung pada; ditentukan oleh.", "penjelasan": "Pola: 名詞 + にかかっている. Menunjukkan bahwa hasil akhir sangat bergantung pada faktor tertentu.", "contoh_jp": "成功するかどうかは、君の努力にかかっている。", "contoh_id": "Apakah berhasil atau tidak bergantung pada usahamu."}, {"jp": "～にかたくない", "meaning_id": "tidak sulit untuk; mudah untuk dibayangkan.", "penjelasan": "Pola: 動詞辞書形 + にかたくない. Biasanya digunakan untuk sesuatu yang mudah dibayangkan atau dipahami secara emosional/intelektual.", "contoh_jp": "彼の苦労は想像にかたくない。", "contoh_id": "Kesulitan yang dialaminya mudah untuk dibayangkan."}, {"jp": "～にまつわる", "meaning_id": "berkaitan dengan; berhubungan dengan; seputar.", "penjelasan": "Pola: 名詞 + にまつわる + 名詞. Digunakan untuk hal-hal yang berhubungan atau memiliki kaitan dengan suatu topik.", "contoh_jp": "日本の歴史にまつわる話を聞いた。", "contoh_id": "Saya mendengar cerita yang berkaitan dengan sejarah Jepang."}, {"jp": "～にもほどがある", "meaning_id": "ada batasnya; terlalu berlebihan; sudah keterlaluan.", "penjelasan": "Digunakan untuk menegur atau mengkritik sesuatu yang dianggap sudah melewati batas kewajaran.", "contoh_jp": "冗談にもほどがある。", "contoh_id": "Bercandanya juga ada batasnya."}, {"jp": "～にもまして", "meaning_id": "lebih dari; bahkan lebih daripada.", "penjelasan": "Pola: 名詞 + にもまして. Digunakan untuk menunjukkan bahwa sesuatu memiliki tingkat yang lebih tinggi dibandingkan keadaan atau waktu sebelumnya.", "contoh_jp": "去年にもまして、今年は忙しい。", "contoh_id": "Tahun ini lebih sibuk lagi dibandingkan tahun lalu."}, {"jp": "～に則って", "meaning_id": "sesuai dengan; berdasarkan; mengikuti.", "penjelasan": "Pola: 名詞 + に則って. Digunakan ketika tindakan dilakukan sesuai aturan, prinsip, contoh, atau standar tertentu.", "contoh_jp": "法律に則って手続きを進める。", "contoh_id": "Prosedur akan dilaksanakan sesuai dengan hukum."}, {"jp": "～に先駆けて", "meaning_id": "mendahului; lebih dahulu daripada; sebagai yang pertama.", "penjelasan": "Menunjukkan bahwa sesuatu dilakukan sebelum pihak lain atau sebelum suatu peristiwa utama terjadi.", "contoh_jp": "本格的な販売に先駆けて、試験販売を行った。", "contoh_id": "Sebelum penjualan resmi dimulai, dilakukan penjualan percobaan terlebih dahulu."}, {"jp": "～にしたって", "meaning_id": "bahkan jika; sekalipun; kalaupun.", "penjelasan": "Merupakan bentuk percakapan/formal ringan yang digunakan untuk menunjukkan pengecualian atau kondisi ekstrem.", "contoh_jp": "彼にしたって、そんな結果になるとは思わなかっただろう。", "contoh_id": "Bahkan dia sendiri pun mungkin tidak menyangka hasilnya akan seperti itu."}, {"jp": "～にして", "meaning_id": "pada; hanya setelah; sekaligus.", "penjelasan": "Pola ini memiliki beberapa fungsi. Salah satunya menunjukkan titik waktu tertentu atau keadaan khusus.", "contoh_jp": "彼は 30 歳にして会社を設立した。", "contoh_id": "Pada usia 30 tahun, dia mendirikan perusahaan."}, {"jp": "～に即して", "meaning_id": "sesuai dengan; berdasarkan keadaan nyata.", "penjelasan": "Menunjukkan bahwa sesuatu dilakukan dengan mempertimbangkan situasi, kenyataan, atau kondisi aktual.", "contoh_jp": "現実に即して計画を見直す必要がある。", "contoh_id": "Kita perlu meninjau kembali rencana sesuai dengan kondisi nyata."}, {"jp": "～にたえる / ～にたえない", "meaning_id": "layak untuk / tidak sanggup untuk.", "penjelasan": "Memiliki dua penggunaan utama: にたえる → sesuatu cukup layak untuk dilakukan/dinikmati. にたえない → tidak sanggup melihat/mendengar; atau sesuatu tidak layak.", "contoh_jp": "この映画は見るにたえる作品だ。", "contoh_id": "Film ini merupakan karya yang layak ditonton."}, {"jp": "～に足る / ～に足りる", "meaning_id": "cukup untuk; layak untuk.", "penjelasan": "Menunjukkan bahwa sesuatu cukup memenuhi standar atau memiliki nilai yang layak.", "contoh_jp": "彼は信頼するに足る人物だ。", "contoh_id": "Dia adalah orang yang layak dipercaya."}, {"jp": "～に足りない", "meaning_id": "tidak cukup; tidak layak.", "penjelasan": "Menunjukkan bahwa sesuatu tidak memiliki nilai atau tingkat yang cukup untuk dianggap penting atau layak.", "contoh_jp": "それは心配するに足りない問題だ。", "contoh_id": "Itu bukan masalah yang cukup serius untuk dikhawatirkan."}, {"jp": "～に照らして", "meaning_id": "berdasarkan; dengan mengacu pada; menurut.", "penjelasan": "Digunakan ketika sesuatu dinilai atau diputuskan dengan menjadikannya sebagai standar pembanding.", "contoh_jp": "法律に照らして判断する必要がある。", "contoh_id": "Kita perlu mengambil keputusan berdasarkan hukum."}, {"jp": "～にとどまらず", "meaning_id": "tidak terbatas pada; bukan hanya ～ tetapi juga ～.", "penjelasan": "Pola: 名詞 + にとどまらず. Menunjukkan bahwa sesuatu melampaui batas atau cakupan pertama dan mencakup hal lain.", "contoh_jp": "その影響は日本にとどまらず、世界中に広がった。", "contoh_id": "Dampaknya tidak terbatas di Jepang, tetapi menyebar ke seluruh dunia."}, {"jp": "～には及ばない", "meaning_id": "tidak perlu; tidak sampai harus ～.", "penjelasan": "Digunakan untuk mengatakan bahwa suatu tindakan tidak diperlukan karena situasinya tidak sampai sejauh itu.", "contoh_jp": "心配するには及ばない。", "contoh_id": "Tidak perlu khawatir."}, {"jp": "～によらず", "meaning_id": "terlepas dari; tanpa memandang.", "penjelasan": "Menunjukkan bahwa suatu kondisi tidak memengaruhi hasil atau aturan yang berlaku.", "contoh_jp": "年齢によらず、誰でも参加できます。", "contoh_id": "Tanpa memandang usia, siapa pun dapat berpartisipasi."}, {"jp": "～んばかりに", "meaning_id": "seolah-olah; seakan-akan hampir ～.", "penjelasan": "Pola: 動詞ない形 + んばかりに. Menunjukkan tindakan atau keadaan yang terlihat sangat kuat seolah-olah sesuatu benar- benar akan terjadi.", "contoh_jp": "彼は泣かんばかりに喜んだ。", "contoh_id": "Dia sangat gembira seolah-olah hampir menangis."}, {"jp": "～んがため", "meaning_id": "demi; untuk tujuan ～.", "penjelasan": "Pola: 動詞ない形 + んがため する → せんがため. Merupakan bentuk yang sangat formal untuk menyatakan tujuan yang kuat.", "contoh_jp": "夢を実現せんがため、彼は努力を続けた。", "contoh_id": "Demi mewujudkan impiannya, dia terus berusaha."}, {"jp": "～の至り", "meaning_id": "sangat; puncak dari; sebesar-besarnya.", "penjelasan": "Digunakan dalam ungkapan formal untuk menunjukkan perasaan yang mencapai tingkat sangat tinggi.", "contoh_jp": "身に余る光栄の至りです。", "contoh_id": "Saya merasa sangat terhormat."}, {"jp": "～の極み", "meaning_id": "puncak; tingkat yang paling tinggi; sangat ekstrem.", "penjelasan": "Menunjukkan bahwa suatu perasaan atau keadaan mencapai tingkat tertinggi.", "contoh_jp": "感激の極みです。", "contoh_id": "Saya benar-benar sangat terharu."}, {"jp": "～のみか", "meaning_id": "bukan hanya ～ tetapi juga ～.", "penjelasan": "Pola: 普通形 + のみか. Bentuk formal dari だけでなく. Digunakan terutama dalam tulisan formal.", "contoh_jp": "彼は英語のみか、中国語も話せる。", "contoh_id": "Dia tidak hanya bisa berbahasa Inggris, tetapi juga bahasa Mandarin."}, {"jp": "～のなんのって", "meaning_id": "sangat; luar biasa sekali; bukan main.", "penjelasan": "Digunakan dalam bahasa percakapan untuk menekankan tingkat sesuatu yang sangat ekstrem.", "contoh_jp": "昨日は暑いのなんのって、外に出られなかった。", "contoh_id": "Kemarin panasnya bukan main sampai-sampai saya tidak bisa keluar."}, {"jp": "～を踏まえて", "meaning_id": "berdasarkan; dengan mempertimbangkan.", "penjelasan": "Menunjukkan bahwa suatu keputusan atau tindakan dibuat dengan mempertimbangkan informasi, pengalaman, atau hasil sebelumnya.", "contoh_jp": "前回の反省を踏まえて、計画を改善した。", "contoh_id": "Berdasarkan evaluasi dari sebelumnya, kami memperbaiki rencana."}, {"jp": "～を経て", "meaning_id": "melalui; setelah melewati; melalui proses.", "penjelasan": "Menunjukkan bahwa sesuatu terjadi setelah melewati suatu proses, tahap, tempat, atau periode waktu.", "contoh_jp": "多くの経験を経て、彼は成長した。", "contoh_id": "Setelah melalui banyak pengalaman, dia berkembang."}, {"jp": "～をいいことに", "meaning_id": "memanfaatkan ～ sebagai kesempatan untuk melakukan sesuatu, biasanya secara negatif.", "penjelasan": "Menunjukkan seseorang memanfaatkan keadaan yang menguntungkan untuk melakukan sesuatu yang tidak pantas.", "contoh_jp": "彼は誰も見ていないのをいいことに、仕事をさぼった。", "contoh_id": "Karena tidak ada yang melihat, dia memanfaatkan keadaan itu untuk bermalas-malasan dari pekerjaan."}, {"jp": "～を限りに", "meaning_id": "mulai setelah ～; dengan ～ sebagai batas terakhir.", "penjelasan": "Menunjukkan bahwa sesuatu berakhir pada waktu tertentu.", "contoh_jp": "今日を限りに、この仕事を辞めます。", "contoh_id": "Mulai setelah hari ini, saya akan berhenti dari pekerjaan ini."}, {"jp": "～を兼ねて", "meaning_id": "sekaligus untuk tujuan ～.", "penjelasan": "Menunjukkan bahwa satu kegiatan dilakukan sekaligus untuk dua tujuan.", "contoh_jp": "健康維持を兼ねて、毎朝歩いている。", "contoh_id": "Saya berjalan setiap pagi sekaligus untuk menjaga kesehatan."}, {"jp": "～を皮切りに", "meaning_id": "dimulai dari ～; diawali dengan ～.", "penjelasan": "Menunjukkan bahwa suatu kejadian dimulai dari satu peristiwa kemudian berlanjut ke berbagai tempat, kegiatan, atau tahap lainnya.", "contoh_jp": "東京公演を皮切りに、全国でコンサートを行う。", "contoh_id": "Dimulai dari pertunjukan di Tokyo, konser akan diadakan di seluruh Jepang."}, {"jp": "～を機に", "meaning_id": "menjadikan ～ sebagai kesempatan/titik balik.", "penjelasan": "Digunakan ketika suatu peristiwa menjadi kesempatan untuk memulai perubahan atau tindakan baru.", "contoh_jp": "結婚を機に、生活を見直した。", "contoh_id": "Saya menjadikan pernikahan sebagai kesempatan untuk meninjau kembali kehidupan saya."}, {"jp": "～を禁じえない", "meaning_id": "tidak dapat menahan; tidak dapat menahan perasaan ～.", "penjelasan": "Pola: 名詞 + を禁じえない. Digunakan dalam tulisan formal ketika suatu perasaan muncul secara alami dan sulit untuk dikendalikan.", "contoh_jp": "彼の行動には驚きを禁じえない。", "contoh_id": "Saya tidak dapat menahan rasa terkejut terhadap tindakannya."}, {"jp": "～をものともせず", "meaning_id": "tanpa memedulikan; tidak gentar terhadap.", "penjelasan": "Menunjukkan bahwa seseorang tetap melakukan sesuatu meskipun menghadapi kesulitan, bahaya, atau hambatan.", "contoh_jp": "彼は周囲の反対をものともせず、自分の夢を追い続けた。", "contoh_id": "Tanpa gentar terhadap penolakan orang-orang di sekitarnya, dia terus mengejar impiannya."}, {"jp": "～をもって①", "meaning_id": "dengan; menggunakan; melalui.", "penjelasan": "Menunjukkan alat, metode, atau sarana yang digunakan untuk melakukan sesuatu. Sangat formal.", "contoh_jp": "最新の技術をもって問題を解決する。", "contoh_id": "Menyelesaikan masalah dengan menggunakan teknologi terbaru."}, {"jp": "～をもって②", "meaning_id": "pada; terhitung mulai; dengan berakhirnya ～.", "penjelasan": "Digunakan untuk menunjukkan waktu atau titik batas secara formal.", "contoh_jp": "本日をもって営業を終了いたします。", "contoh_id": "Terhitung mulai hari ini, kegiatan operasional kami akan dihentikan."}, {"jp": "～をおいて", "meaning_id": "selain ～; hanya ～.", "penjelasan": "Pola: 名詞 + をおいて + ～ない. Digunakan untuk menyatakan bahwa tidak ada pilihan lain yang lebih tepat selain orang atau benda yang disebutkan.", "contoh_jp": "この仕事を任せられる人は、彼をおいてほかにいない。", "contoh_id": "Tidak ada orang lain selain dia yang dapat dipercaya untuk menangani pekerjaan ini."}, {"jp": "～を余儀なくされる", "meaning_id": "terpaksa; dipaksa oleh keadaan untuk ～.", "penjelasan": "Menunjukkan bahwa seseorang terpaksa melakukan sesuatu karena keadaan di luar kendalinya.", "contoh_jp": "大雨のため、試合の中止を余儀なくされた。", "contoh_id": "Karena hujan deras, pertandingan terpaksa dibatalkan."}, {"jp": "～をよそに", "meaning_id": "tanpa memedulikan; mengabaikan; meskipun ～.", "penjelasan": "Menunjukkan bahwa seseorang melakukan sesuatu tanpa memedulikan kekhawatiran, perhatian, atau reaksi orang lain.", "contoh_jp": "両親の心配をよそに、彼は海外へ旅立った。", "contoh_id": "Tanpa memedulikan kekhawatiran orang tuanya, dia berangkat ke luar negeri."}, {"jp": "～思いをする", "meaning_id": "mengalami perasaan/keadaan ～.", "penjelasan": "Pola: ～という思いをする. Digunakan untuk menyatakan bahwa seseorang mengalami suatu pengalaman atau merasakan suatu keadaan tertentu.", "contoh_jp": "大切な人を失って、つらい思いをした。", "contoh_id": "Saya mengalami masa yang sangat menyakitkan setelah kehilangan orang yang penting bagi saya."}, {"jp": "～折に", "meaning_id": "ketika; pada kesempatan; pada saat.", "penjelasan": "Pola: 動詞辞書形 + 折に 名詞 + の + 折に. Merupakan ungkapan formal untuk menunjukkan kesempatan atau waktu tertentu ketika suatu hal terjadi.", "contoh_jp": "日本へ行った折に、ぜひこちらへお立ち寄りください。", "contoh_id": "Ketika Anda pergi ke Jepang, silakan mampir ke sini."}, {"jp": "およそ", "meaning_id": "kira-kira; kurang lebih; sama sekali (dengan bentuk negatif).", "penjelasan": "Dengan angka, およそ berarti “sekitar/kira-kira”. Dalam pola tertentu seperti およそ～ない, maknanya menjadi “sama sekali tidak”.", "contoh_jp": "およそ 100 人が参加した。", "contoh_id": "Sekitar 100 orang berpartisipasi."}, {"jp": "さもないと", "meaning_id": "kalau tidak; jika tidak demikian; kalau tidak, akibatnya ～.", "penjelasan": "Digunakan untuk menunjukkan peringatan atau konsekuensi apabila suatu tindakan tidak dilakukan.", "contoh_jp": "急いでください。さもないと、電車に間に合いません。", "contoh_id": "Tolong segera. Kalau tidak, kita akan ketinggalan kereta."}, {"jp": "さぞ", "meaning_id": "pasti; saya yakin ～.", "penjelasan": "Digunakan untuk menyatakan dugaan kuat mengenai perasaan atau keadaan seseorang, biasanya berdasarkan situasi yang dapat dibayangkan.", "contoh_jp": "一人で海外へ行くのは、さぞ不安だったでしょう。", "contoh_id": "Pergi ke luar negeri sendirian pasti sangat mencemaskan, ya."}, {"jp": "～始末だ", "meaning_id": "akhirnya sampai pada keadaan ～; berakhir dengan ～.", "penjelasan": "Biasanya digunakan untuk menjelaskan perkembangan suatu masalah yang akhirnya berujung pada keadaan buruk atau tidak diinginkan.", "contoh_jp": "仕事を怠け続けた結果、会社を辞める始末となった。", "contoh_id": "Akibat terus bermalas-malasan dalam pekerjaan, akhirnya dia sampai harus keluar dari perusahaan."}, {"jp": "～そばから", "meaning_id": "segera setelah; setiap kali baru saja ～.", "penjelasan": "Pola: 動詞辞書形 / た形 + そばから. Menunjukkan bahwa sesuatu yang baru saja dilakukan segera mengalami keadaan yang sama lagi, sehingga seolah-olah usaha tersebut sia-sia.", "contoh_jp": "教えたそばから、彼は忘れてしまう。", "contoh_id": "Begitu saja diajarkan, dia langsung melupakannya lagi."}, {"jp": "さも", "meaning_id": "seolah-olah; benar-benar; dengan sangat meyakinkan.", "penjelasan": "Sering digunakan bersama ～かのように untuk menunjukkan tindakan yang tampak seolah- olah benar.", "contoh_jp": "彼はさも自分が正しいかのように話している。", "contoh_id": "Dia berbicara seolah-olah dirinya benar."}, {"jp": "それなりに", "meaning_id": "dengan caranya sendiri; sesuai dengan tingkatnya; cukup.", "penjelasan": "Menunjukkan bahwa sesuatu memiliki kualitas atau hasil yang sesuai dengan keadaan, kemampuan, atau tingkat tertentu.", "contoh_jp": "難しい仕事だったが、それなりに楽しめた。", "contoh_id": "Meskipun pekerjaan itu sulit, saya tetap bisa menikmatinya dengan cara saya sendiri."}, {"jp": "～そうにもない", "meaning_id": "tampaknya tidak mungkin; sepertinya tidak akan ～.", "penjelasan": "Menunjukkan bahwa berdasarkan keadaan sekarang, kemungkinan suatu tindakan atau kejadian terjadi sangat kecil.", "contoh_jp": "この問題は今日中には解決しそうにもない。", "contoh_id": "Sepertinya masalah ini tidak mungkin selesai hari ini."}, {"jp": "ただ～のみだ", "meaning_id": "hanya bisa ～; tidak ada yang dapat dilakukan selain ～.", "penjelasan": "Menunjukkan bahwa satu-satunya tindakan yang tersisa hanyalah sesuatu yang disebutkan.", "contoh_jp": "今は結果を待つのみだ。", "contoh_id": "Sekarang yang bisa dilakukan hanyalah menunggu hasil."}, {"jp": "～た拍子に", "meaning_id": "tepat ketika; pada saat ～ secara tidak sengaja.", "penjelasan": "Menunjukkan bahwa suatu kejadian terjadi tepat ketika melakukan tindakan tertentu, biasanya secara tidak disengaja.", "contoh_jp": "ドアを開けた拍子に、荷物が落ちた。", "contoh_id": "Tepat ketika membuka pintu, barang bawaan saya jatuh."}, {"jp": "～たためしがない", "meaning_id": "tidak pernah sekalipun; tidak ada contoh bahwa ～.", "penjelasan": "Digunakan untuk mengatakan bahwa sesuatu tidak pernah terjadi, biasanya berdasarkan pengalaman berulang.", "contoh_jp": "彼は約束を守ったためしがない。", "contoh_id": "Dia tidak pernah sekalipun menepati janji."}, {"jp": "～たりとも", "meaning_id": "bahkan satu pun; bahkan sedikit pun.", "penjelasan": "Biasanya digunakan dengan angka kecil atau jumlah minimum untuk menekankan bahwa bahkan jumlah sekecil itu pun tidak diperbolehkan atau tidak ada.", "contoh_jp": "一日たりとも休んではならない。", "contoh_id": "Tidak boleh beristirahat bahkan satu hari pun."}, {"jp": "～た瞬間に", "meaning_id": "tepat pada saat; begitu ～.", "penjelasan": "Menunjukkan bahwa kejadian kedua berlangsung tepat ketika tindakan pertama selesai.", "contoh_jp": "家を出た瞬間に、雨が降り始めた。", "contoh_id": "Tepat saat saya keluar rumah, hujan mulai turun."}, {"jp": "てっきり", "meaning_id": "saya yakin; saya kira pasti.", "penjelasan": "Digunakan ketika seseorang sangat yakin terhadap suatu dugaan, tetapi ternyata dugaan tersebut salah.", "contoh_jp": "てっきり彼はもう帰ったと思っていた。", "contoh_id": "Saya benar-benar mengira dia sudah pulang."}, {"jp": "～たところで", "meaning_id": "sekalipun ～; meskipun melakukan ～.", "penjelasan": "Pola: 動詞た形 + ところで. Menunjukkan bahwa meskipun suatu tindakan dilakukan, hasil yang diharapkan tetap tidak akan tercapai atau tidak banyak berubah.", "contoh_jp": "今から急いだところで、間に合わないだろう。", "contoh_id": "Sekalipun mulai terburu-buru sekarang, mungkin tetap tidak akan sempat."}, {"jp": "～てからというもの", "meaning_id": "sejak ～; semenjak ～.", "penjelasan": "Menunjukkan bahwa setelah suatu peristiwa terjadi, keadaan berikutnya terus berlangsung hingga sekarang.", "contoh_jp": "日本に来てからというもの、毎日日本語を使っている。", "contoh_id": "Semenjak datang ke Jepang, saya menggunakan bahasa Jepang setiap hari."}, {"jp": "～てかなわない", "meaning_id": "tidak tahan; sangat mengganggu; tidak sanggup menghadapi.", "penjelasan": "Pola: イ形容詞て + かなわない ナ形容詞で + かなわない. Digunakan ketika suatu keadaan sangat mengganggu atau membuat seseorang merasa tidak tahan.", "contoh_jp": "毎日暑くてかなわない。", "contoh_id": "Setiap hari panas sekali sampai saya tidak tahan."}, {"jp": "～てまで", "meaning_id": "sampai-sampai melakukan ～; bahkan rela melakukan ～.", "penjelasan": "Menunjukkan bahwa seseorang melakukan sesuatu yang ekstrem atau dianggap berlebihan demi mencapai tujuan tertentu.", "contoh_jp": "嘘をついてまで成功したくない。", "contoh_id": "Saya tidak ingin berhasil sampai harus berbohong."}, {"jp": "～てみせる", "meaning_id": "pasti akan ～; akan membuktikan bahwa saya bisa ～.", "penjelasan": "Menunjukkan tekad kuat untuk melakukan atau menyelesaikan sesuatu.", "contoh_jp": "必ず試験に合格してみせる。", "contoh_id": "Saya pasti akan lulus ujian."}, {"jp": "～てもどうにもならない", "meaning_id": "percuma meskipun ～; tidak ada gunanya.", "penjelasan": "Menunjukkan bahwa melakukan sesuatu tidak akan mengubah keadaan atau menyelesaikan masalah.", "contoh_jp": "今さら後悔してもどうにもならない。", "contoh_id": "Percuma menyesal sekarang, karena tidak akan mengubah apa pun."}, {"jp": "～ても始まらない", "meaning_id": "percuma jika ～; tidak ada gunanya ～.", "penjelasan": "Digunakan ketika suatu tindakan tidak menghasilkan kemajuan atau solusi apa pun.", "contoh_jp": "文句を言っても始まらない。", "contoh_id": "Percuma mengeluh."}, {"jp": "～ても差し支えない", "meaning_id": "tidak masalah jika ～; boleh ～.", "penjelasan": "Bentuk formal dan sopan untuk mengatakan bahwa suatu tindakan diperbolehkan atau tidak menimbulkan masalah.", "contoh_jp": "ここに座っても差し支えありません。", "contoh_id": "Tidak masalah jika Anda duduk di sini."}, {"jp": "～てしかるべきだ", "meaning_id": "sudah sewajarnya ～; seharusnya ～.", "penjelasan": "Digunakan untuk menyatakan bahwa sesuatu memang sepatutnya terjadi berdasarkan keadaan atau alasan yang ada.", "contoh_jp": "彼はもっと評価されてしかるべきだ。", "contoh_id": "Dia sudah seharusnya mendapatkan penghargaan yang lebih tinggi."}, {"jp": "～ってば", "meaning_id": "sudah saya bilang; saya sudah bilang kepadamu.", "penjelasan": "Bentuk percakapan yang digunakan untuk menegaskan kembali perkataan karena lawan bicara tidak mendengarkan atau tidak memahami.", "contoh_jp": "もう帰るってば！", "contoh_id": "Sudah kubilang, aku mau pulang!"}, {"jp": "～てやまない", "meaning_id": "terus-menerus; tidak pernah berhenti ～.", "penjelasan": "Biasanya digunakan dalam bahasa formal untuk menunjukkan harapan, perasaan, atau keinginan yang terus ada.", "contoh_jp": "皆様のご健康を願ってやみません。", "contoh_id": "Saya senantiasa mendoakan kesehatan Anda semua."}, {"jp": "～と相まって", "meaning_id": "ditambah dengan; berpadu dengan.", "penjelasan": "Pola: 名詞 + と相まって. Menunjukkan bahwa dua faktor bergabung sehingga menghasilkan efek tertentu.", "contoh_jp": "美しい景色と相まって、料理がさらにおいしく感じられた。", "contoh_id": "Ditambah dengan pemandangan yang indah, makanan terasa semakin lezat."}, {"jp": "～とあれば", "meaning_id": "jika memang ～; jika keadaannya seperti itu.", "penjelasan": "Menunjukkan bahwa jika kondisi tertentu benar-benar terjadi, maka pembicara bersedia melakukan sesuatu yang biasanya tidak dilakukan.", "contoh_jp": "君のためとあれば、何でもする。", "contoh_id": "Kalau itu demi kamu, saya akan melakukan apa saja."}, {"jp": "～とあって", "meaning_id": "karena; mengingat bahwa ～.", "penjelasan": "Menunjukkan alasan berupa keadaan khusus yang menyebabkan hasil tertentu.", "contoh_jp": "人気歌手が来るとあって、会場は大勢の人でいっぱいだった。", "contoh_id": "Karena penyanyi populer akan datang, tempat acara dipenuhi banyak orang."}, {"jp": "～とばかりに", "meaning_id": "seolah-olah mengatakan; seakan-akan ingin mengatakan.", "penjelasan": "Digunakan ketika ekspresi atau tindakan seseorang terlihat seperti menyampaikan pesan tertentu tanpa mengatakannya secara langsung.", "contoh_jp": "彼は「早く帰れ」とばかりに私を見た。", "contoh_id": "Dia melihat saya seolah-olah berkata, “Cepat pulang.”"}, {"jp": "～といえども", "meaning_id": "meskipun; sekalipun.", "penjelasan": "Merupakan bentuk sangat formal dari ～ても. Sering ditemukan dalam tulisan resmi.", "contoh_jp": "子供といえども、責任を持つべきだ。", "contoh_id": "Meskipun masih anak-anak, seseorang tetap harus bertanggung jawab."}, {"jp": "～といい～といい", "meaning_id": "baik dari segi ～ maupun ～; dilihat dari ～ maupun ～.", "penjelasan": "Pola: 名詞 + といい + 名詞 + といい. Digunakan untuk menyebutkan dua aspek yang sama-sama menjadi dasar penilaian.", "contoh_jp": "この車はデザインといい性能といい、素晴らしい。", "contoh_id": "Mobil ini luar biasa, baik dari segi desain maupun performanya."}, {"jp": "～といったらない", "meaning_id": "sangat; luar biasa; bukan main.", "penjelasan": "Digunakan untuk menekankan tingkat suatu perasaan atau keadaan yang sangat ekstrem.", "contoh_jp": "試験の結果を聞いたときのうれしさといったらなかった。", "contoh_id": "Rasa bahagia ketika mendengar hasil ujian itu sungguh luar biasa."}, {"jp": "～という", "meaning_id": "setiap; semua; seluruh.", "penjelasan": "Dalam pola tertentu, という digunakan untuk memberikan penekanan bahwa seluruh anggota dalam suatu kelompok memiliki kondisi yang sama.", "contoh_jp": "町という町が祭りでにぎわっていた。", "contoh_id": "Semua kota dipenuhi kemeriahan festival."}, {"jp": "～というか", "meaning_id": "atau lebih tepatnya; bagaimana mengatakannya.", "penjelasan": "Digunakan ketika pembicara ingin mengoreksi atau memperhalus ungkapan yang baru saja dikatakan.", "contoh_jp": "彼は優しいというか、少しおとなしい人だ。", "contoh_id": "Dia itu baik, atau lebih tepatnya agak pendiam."}, {"jp": "～というか～というか", "meaning_id": "entah A atau B; sulit mengatakan apakah A atau B.", "penjelasan": "Digunakan ketika pembicara kesulitan menentukan kata yang tepat untuk menggambarkan sesuatu.", "contoh_jp": "彼は親切というか、おせっかいというか、少し複雑な人だ。", "contoh_id": "Dia itu bisa dibilang baik, atau mungkin terlalu suka ikut campur; orangnya agak sulit dijelaskan."}, {"jp": "～というところだ / ～といったところだ", "meaning_id": "sekitar; kurang lebih; kira-kira sebatas ～.", "penjelasan": "Digunakan untuk memberikan perkiraan jumlah, tingkat, atau keadaan.", "contoh_jp": "参加者は 100 人といったところだ。", "contoh_id": "Jumlah pesertanya sekitar 100 orang."}, {"jp": "～というもの", "meaning_id": "selama periode; sejak ～.", "penjelasan": "Digunakan untuk menunjukkan bahwa suatu keadaan terus berlangsung selama periode tertentu.", "contoh_jp": "この 1 週間というもの、毎日雨が降っている。", "contoh_id": "Selama satu minggu ini, setiap hari turun hujan."}, {"jp": "～というわけだ", "meaning_id": "berarti; jadi; dengan demikian.", "penjelasan": "Digunakan untuk menunjukkan kesimpulan yang diperoleh dari informasi sebelumnya.", "contoh_jp": "彼は 10 年間日本に住んでいた。つまり、日本語が上手なわけだ。", "contoh_id": "Dia tinggal di Jepang selama 10 tahun. Jadi, wajar kalau bahasa Jepangnya bagus."}, {"jp": "～というわけではない", "meaning_id": "bukan berarti ～; bukan berarti bahwa ～.", "penjelasan": "Digunakan untuk menyangkal kesimpulan yang terlalu umum.", "contoh_jp": "日本人だからといって、誰もが日本語を教えられるというわけではない。", "contoh_id": "Bukan berarti setiap orang Jepang bisa mengajarkan bahasa Jepang."}, {"jp": "～といわず", "meaning_id": "tidak hanya ～; baik ～ maupun ～.", "penjelasan": "Menunjukkan bahwa bukan hanya bagian tertentu, tetapi juga bagian lainnya mengalami keadaan yang sama.", "contoh_jp": "子供といわず大人といわず、みんな楽しんでいた。", "contoh_id": "Baik anak-anak maupun orang dewasa, semuanya bersenang-senang."}, {"jp": "～ときたら", "meaning_id": "kalau membicarakan ～; mengenai ～.", "penjelasan": "Sering digunakan untuk mengeluhkan atau mengkritik seseorang atau sesuatu.", "contoh_jp": "うちの息子ときたら、全然勉強しない。", "contoh_id": "Kalau anak saya itu, sama sekali tidak mau belajar."}, {"jp": "～ときている", "meaning_id": "karena memang ～; ditambah lagi ～.", "penjelasan": "Digunakan untuk menambahkan alasan yang semakin memperkuat suatu penilaian atau keadaan.", "contoh_jp": "彼は仕事が遅い。そのうえ、ミスも多いときている。", "contoh_id": "Dia lambat dalam bekerja. Ditambah lagi, dia juga sering melakukan kesalahan."}, {"jp": "～ところがある", "meaning_id": "memiliki sisi/aspek ～; ada bagian yang ～.", "penjelasan": "Digunakan untuk menunjukkan bahwa seseorang atau sesuatu memiliki karakteristik tertentu, meskipun tidak sepenuhnya demikian.", "contoh_jp": "彼には少し頑固なところがある。", "contoh_id": "Dia memiliki sisi yang agak keras kepala."}, {"jp": "～ところから", "meaning_id": "berdasarkan fakta bahwa ～; dari kenyataan bahwa ～.", "penjelasan": "Digunakan untuk menunjukkan dasar atau petunjuk yang menjadi alasan suatu kesimpulan.", "contoh_jp": "彼が何も言わないところから、反対ではないと思う。", "contoh_id": "Dari kenyataan bahwa dia tidak mengatakan apa-apa, saya rasa dia tidak menentangnya."}, {"jp": "～とみられる", "meaning_id": "diperkirakan; dianggap; dipandang sebagai.", "penjelasan": "Sering digunakan dalam berita, laporan, dan tulisan formal untuk menyatakan perkiraan berdasarkan bukti.", "contoh_jp": "今後も物価は上昇するとみられている。", "contoh_id": "Harga-harga diperkirakan akan terus meningkat."}, {"jp": "～とみるや", "meaning_id": "begitu melihat ～; segera setelah menyadari ～.", "penjelasan": "Menunjukkan bahwa segera setelah seseorang melihat atau menyadari sesuatu, ia langsung melakukan tindakan tertentu.", "contoh_jp": "チャンスとみるや、彼はすぐに行動した。", "contoh_id": "Begitu melihat adanya kesempatan, dia langsung bertindak."}, {"jp": "～ともなく", "meaning_id": "tanpa sengaja; tanpa benar-benar bermaksud.", "penjelasan": "Pola: 動詞辞書形 + ともなく. Digunakan ketika seseorang melakukan sesuatu tanpa tujuan atau perhatian khusus.", "contoh_jp": "テレビを見るともなく見ていた。", "contoh_id": "Saya menonton televisi tanpa benar-benar memperhatikannya."}, {"jp": "～ともなると / ～ともなれば", "meaning_id": "ketika sudah sampai pada tahap ～; apabila sudah menjadi ～.", "penjelasan": "Menunjukkan bahwa ketika seseorang mencapai kondisi atau tahap tertentu, keadaan yang berbeda akan muncul.", "contoh_jp": "社会人ともなると、自分の行動に責任を持たなければならない。", "contoh_id": "Ketika sudah menjadi anggota masyarakat yang bekerja, seseorang harus bertanggung jawab atas tindakannya sendiri."}, {"jp": "～ともすれば", "meaning_id": "cenderung; mudah sekali untuk ～.", "penjelasan": "Menunjukkan kecenderungan bahwa sesuatu mudah terjadi, terutama dalam kondisi tertentu.", "contoh_jp": "忙しいと、ともすれば健康を忘れがちになる。", "contoh_id": "Ketika sibuk, seseorang cenderung melupakan kesehatan."}, {"jp": "～と思いきや", "meaning_id": "saya kira ～, ternyata ～.", "penjelasan": "Digunakan ketika hasil atau kenyataan ternyata berlawanan dengan apa yang sebelumnya diperkirakan.", "contoh_jp": "今日は休みだと思いきや、仕事が入っていた。", "contoh_id": "Saya kira hari ini libur, ternyata ada pekerjaan."}, {"jp": "とりわけ", "meaning_id": "terutama; khususnya.", "penjelasan": "Digunakan untuk menyoroti satu hal yang dianggap lebih menonjol dibandingkan yang lainnya.", "contoh_jp": "この地域は冬が長く、とりわけ 1 月は寒い。", "contoh_id": "Musim dingin di daerah ini panjang, dan khususnya bulan Januari sangat dingin."}, {"jp": "～とされる", "meaning_id": "dianggap; dipandang sebagai; dikatakan sebagai.", "penjelasan": "Digunakan ketika suatu pendapat atau fakta diakui atau dianggap demikian secara umum, bukan semata-mata pendapat pribadi pembicara.", "contoh_jp": "この建物は江戸時代に建てられたとされている。", "contoh_id": "Bangunan ini dianggap dibangun pada zaman Edo."}, {"jp": "とっさに", "meaning_id": "secara spontan; seketika; secara refleks.", "penjelasan": "Menunjukkan tindakan yang dilakukan secara spontan tanpa sempat berpikir panjang.", "contoh_jp": "とっさに手を伸ばして、子供を助けた。", "contoh_id": "Secara refleks, saya mengulurkan tangan dan menyelamatkan anak itu."}, {"jp": "～としたって / ～としたところで", "meaning_id": "sekalipun; bahkan jika.", "penjelasan": "Menunjukkan bahwa meskipun suatu kondisi terpenuhi, hasil akhirnya tetap tidak berubah.", "contoh_jp": "今から出発したとしたって、間に合わない。", "contoh_id": "Sekalipun berangkat sekarang, tetap tidak akan sempat."}, {"jp": "～として～ない", "meaning_id": "bahkan satu pun tidak.", "penjelasan": "Pola: 一人として～ない 一つとして～ない. Digunakan untuk menekankan bahwa tidak ada satu pun dari jumlah atau kelompok tertentu yang memenuhi kondisi tersebut.", "contoh_jp": "参加者の中に一人として反対する人はいなかった。", "contoh_id": "Tidak ada satu orang pun di antara peserta yang menentang."}, {"jp": "～とて", "meaning_id": "sekalipun; meskipun.", "penjelasan": "Merupakan bentuk formal/klasik yang digunakan untuk menunjukkan konsesi atau pengecualian.", "contoh_jp": "私とて、何も知らないわけではない。", "contoh_id": "Meskipun saya, bukan berarti saya tidak tahu apa-apa."}, {"jp": "とても～ない", "meaning_id": "sama sekali tidak mungkin; tidak mungkin dapat ～.", "penjelasan": "Dalam pola ini とても bukan berarti “sangat”, tetapi digunakan untuk menegaskan bahwa sesuatu benar-benar mustahil dilakukan.", "contoh_jp": "こんな重い荷物はとても一人では運べない。", "contoh_id": "Barang seberat ini sama sekali tidak mungkin dibawa sendirian."}, {"jp": "～とは", "meaning_id": "apa yang dimaksud dengan ～; menunjukkan istilah yang akan dijelaskan.", "penjelasan": "Digunakan untuk menyoroti suatu kata atau ungkapan yang kemudian diberikan definisi atau penjelasan.", "contoh_jp": "「敬語」とは、相手に敬意を表すための言葉です。", "contoh_id": "“Keigo” adalah bahasa yang digunakan untuk menunjukkan rasa hormat kepada lawan bicara."}, {"jp": "～とはいえ", "meaning_id": "meskipun demikian; walaupun begitu.", "penjelasan": "Digunakan untuk mengakui suatu fakta, lalu menyampaikan hal yang berlawanan atau membatasi pernyataan sebelumnya.", "contoh_jp": "春とはいえ、朝晩はまだ寒い。", "contoh_id": "Meskipun sudah musim semi, pagi dan malam masih dingin."}, {"jp": "～とはいうものの", "meaning_id": "meskipun demikian; walaupun dikatakan demikian.", "penjelasan": "Mirip dengan とはいえ, tetapi digunakan untuk mengakui pernyataan sebelumnya lalu memberikan kenyataan yang berbeda.", "contoh_jp": "簡単だとはいうものの、実際にやってみると難しい。", "contoh_id": "Meskipun dikatakan mudah, ketika benar-benar mencobanya ternyata sulit."}, {"jp": "～つ～つ", "meaning_id": "melakukan A dan B secara bergantian; saling ～.", "penjelasan": "Pola: 動詞ます形語幹 + つ + 動詞ます形語幹 + つ. Digunakan untuk menunjukkan dua tindakan yang berlawanan atau dilakukan secara bergantian.", "contoh_jp": "電車の中で、立ちつ座りつしていた。", "contoh_id": "Di dalam kereta, saya berdiri dan duduk secara bergantian."}, {"jp": "～はおろか", "meaning_id": "jangankan ～; apalagi ～; belum lagi ～.", "penjelasan": "Digunakan ketika hal yang lebih mudah atau dasar saja tidak tercapai, apalagi hal yang lebih tinggi.", "contoh_jp": "彼は英語はおろか、日本語も十分に話せない。", "contoh_id": "Jangankan bahasa Inggris, bahasa Jepangnya saja tidak dapat dia gunakan dengan baik."}, {"jp": "～はさておき", "meaning_id": "mengesampingkan; terlepas dari; untuk sementara tidak membahas ～.", "penjelasan": "Digunakan ketika pembicara sengaja tidak membahas satu hal dan beralih ke hal yang lebih penting.", "contoh_jp": "冗談はさておき、本題に入りましょう。", "contoh_id": "Terlepas dari candaan, mari kita masuk ke pokok pembicaraan."}, {"jp": "～や否や", "meaning_id": "begitu ～; segera setelah ～.", "penjelasan": "Pola: 動詞辞書形 + や否や. Menunjukkan bahwa kejadian kedua terjadi segera setelah kejadian pertama, dengan nuansa sangat cepat.", "contoh_jp": "先生が教室に入るや否や、学生たちは静かになった。", "contoh_id": "Begitu guru masuk kelas, para siswa langsung menjadi tenang."}, {"jp": "～やしない", "meaning_id": "sama sekali tidak; tidak akan ～.", "penjelasan": "Bentuk penegasan negatif yang digunakan untuk menekankan bahwa sesuatu benar-benar tidak terjadi.", "contoh_jp": "そんなこと、誰も信じやしない。", "contoh_id": "Tidak ada seorang pun yang akan percaya hal seperti itu."}, {"jp": "（よ）うが / （よ）うと", "meaning_id": "bagaimanapun; apa pun; tidak peduli bagaimana.", "penjelasan": "Pola: 動詞意向形 + が / と イ形容詞語幹 + かろうが ナ形容詞 + であろうが. Menunjukkan bahwa hasil atau keadaan tidak berubah meskipun kondisinya berbeda.", "contoh_jp": "何を言われようが、私は自分の考えを変えない。", "contoh_id": "Apa pun yang dikatakan kepada saya, saya tidak akan mengubah pendirian saya."}, {"jp": "（よ）うが～まいが / （よ）うと～まいと", "meaning_id": "entah ～ atau tidak; baik ～ maupun tidak.", "penjelasan": "Menunjukkan bahwa hasil tidak berubah terlepas dari apakah suatu tindakan dilakukan atau tidak.", "contoh_jp": "彼が来ようが来まいが、会議は始めます。", "contoh_id": "Entah dia datang atau tidak, rapat akan dimulai."}, {"jp": "（よ）うか～まいか", "meaning_id": "apakah akan ～ atau tidak.", "penjelasan": "Digunakan ketika seseorang sedang mempertimbangkan apakah akan melakukan sesuatu atau tidak.", "contoh_jp": "日本へ行こうか行くまいか、まだ決めていない。", "contoh_id": "Saya belum memutuskan apakah akan pergi ke Jepang atau tidak."}, {"jp": "（よ）うものなら", "meaning_id": "kalau sampai berani ～; jika sampai melakukan ～.", "penjelasan": "Menunjukkan bahwa jika seseorang sampai melakukan sesuatu, kemungkinan besar akan muncul akibat yang buruk atau serius.", "contoh_jp": "そんなことを言おうものなら、彼は怒るだろう。", "contoh_id": "Kalau sampai mengatakan hal seperti itu, dia pasti akan marah."}, {"jp": "（よ）うにも～ない", "meaning_id": "meskipun ingin/berusaha ～, tidak bisa ～.", "penjelasan": "Menunjukkan bahwa seseorang ingin melakukan sesuatu atau mencoba melakukannya, tetapi ada hambatan yang membuatnya mustahil.", "contoh_jp": "忘れようにも忘れられない。", "contoh_id": "Meskipun ingin melupakan, saya tidak bisa melupakannya."}, {"jp": "～ようによっては", "meaning_id": "tergantung bagaimana ～; tergantung cara ～.", "penjelasan": "Menunjukkan bahwa hasil dapat berbeda tergantung bagaimana sesuatu dilakukan atau digunakan.", "contoh_jp": "この問題は考えようによっては簡単だ。", "contoh_id": "Tergantung cara memikirkannya, masalah ini sebenarnya mudah."}, {"jp": "ゆえに", "meaning_id": "oleh karena itu; karena itu; akibatnya.", "penjelasan": "Pola: 名詞 + ゆえに 普通形 + ゆえに. Bentuk formal dari だから / そのため. Banyak digunakan dalam tulisan formal dan akademik.", "contoh_jp": "経験が少ないゆえに、判断を誤ることもある。", "contoh_id": "Karena kurang pengalaman, seseorang terkadang dapat melakukan kesalahan dalam mengambil keputusan."}, {"jp": "～ざる", "meaning_id": "tidak ～.", "penjelasan": "Pola: 動詞ない形語幹 + ざる. Merupakan bentuk negatif klasik dari kata kerja. Sering ditemukan dalam bahasa formal, tulisan, atau ungkapan tetap.", "contoh_jp": "努力せざる者に成功はない。", "contoh_id": "Tidak ada keberhasilan bagi orang yang tidak berusaha."}, {"jp": "～ずじまい", "meaning_id": "akhirnya tidak sempat ～; berakhir tanpa pernah ～.", "penjelasan": "Pola: 動詞ない形 + ずじまい. Digunakan ketika seseorang berniat melakukan sesuatu tetapi sampai akhirnya tidak pernah berhasil melakukannya.", "contoh_jp": "日本へ行ったが、富士山を見ることができずじまいだった。", "contoh_id": "Saya pergi ke Jepang, tetapi akhirnya tidak sempat melihat Gunung Fuji."}, {"jp": "～ずくめ", "meaning_id": "penuh dengan; seluruhnya; semuanya ～.", "penjelasan": "Pola: 名詞 + ずくめ. Menunjukkan bahwa sesuatu dipenuhi oleh satu jenis keadaan atau karakteristik.", "contoh_jp": "今日は朝から良いことずくめだった。", "contoh_id": "Hari ini sejak pagi semuanya dipenuhi hal-hal yang baik."}, {"jp": "～ずとも", "meaning_id": "bahkan tanpa ～; meskipun tidak ～.", "penjelasan": "Pola: 動詞ない形 + ずとも. Merupakan bentuk formal dari ～なくても. Menunjukkan bahwa suatu tindakan tidak perlu dilakukan agar sesuatu tetap dapat terjadi.", "contoh_jp": "説明せずとも、彼なら理解できるだろう。", "contoh_id": "Bahkan tanpa dijelaskan pun, dia mungkin bisa memahaminya."}];
